Object.assign(window.TEM8_DICTIONARY, {"vengeance":{"media":{"uk":"media/uk/vengeance__gb_1.mp3","us":"media/us/vengeance__us_1.mp3"},"oxford":{"phon":"ˈvendʒəns","pos":"noun","senses":[{"en":"the act of punishing or harming somebody in return for what they have done to you, your family or friends","cn":"报复；报仇；复仇","ex":{"en":"a desire for vengeance","cn":"复仇心"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"复仇;报复;报仇","en":"Vengeance is the act of killing, injuring, or harming someone because they have harmed you.","ex":{"en":"He swore vengeance on everyone involved in the murder","cn":"他发誓要报复每一个参与了这起谋杀的人。"}},{"pos":"PHRASE 短语","cn":"过度地;猛烈地;激烈地","en":"If you say that something happens with a vengeance, you are emphasizing that it happens to a much greater extent than was expected.","ex":{"en":"It began to rain again with a vengeance","cn":"又开始下起了大雨。"}}]},"examples":[{"en":"He swore vengeance on his child's killer.","cn":"他发誓要找杀害他孩子的凶手报仇。"},{"en":"She set to work with a vengeance.","cn":"她加倍努力地工作起来。"}]},"verdict":{"oxford":{"phon":"ˈvɜːdɪkt","pos":"noun","senses":[{"en":"an official judgement made in court or at an inquest (= an official investigation into somebody's death)","cn":"（法庭或死因审理的）裁定，裁决，裁断","lab":"especially North American English","ex":{"en":"Has the jury reached a verdict?","cn":"陪审团作出裁定了吗？"}},{"en":"a decision that you make or an opinion that you give about something, after you have tested it or considered it carefully","cn":"（经过检验或认真考虑后的）决定，结论，意见","ex":{"en":"Well, what's your verdict?","cn":"那么，你有何意见呢？"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（陪审团或法官的）裁决，裁定，裁断","en":"In a court of law, the verdict is the decision that is given by the jury or judge at the end of a trial.","ex":{"en":"The jury returned a unanimous guilty verdict","cn":"陪审团一致作出了有罪裁决。"}},{"pos":"N-COUNT 可数名词","cn":"（经过思考或调查后的）意见，结论","en":"Someone's verdict on something is their opinion of it, after thinking about it or investigating it.","ex":{"en":"The doctor's verdict was that he was entirely healthy","cn":"医生的结论是他完全健康。"}}]},"media":{"uk":"media/uk/verdict__gb_1.mp3","us":"media/us/verdict__us_1.mp3"},"examples":[{"en":"The panel will give their verdict on the latest video releases.","cn":"专题组将就最近发行的录像提出他们的意见。"},{"en":"The coroner recorded a verdict of accidental death.","cn":"验尸官得出了意外死亡的结论。"}]},"verve":{"media":{"uk":"media/uk/verve__gb_1.mp3","us":"media/us/verve__us_1.mp3"},"oxford":{"phon":"vɜːv","pos":"noun","senses":[{"en":"energy, excitement or enthusiasm","cn":"精力；激情；热情；热忱","ex":{"en":"It was a performance of verve and vitality.","cn":"这是一场充满激情与活力的演出。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"活力;热情;激情","en":"Verve is lively and forceful enthusiasm.","ex":{"en":"He looked for the dramatic, like the sunset in this painting, and painted it with great verve","cn":"他追求画面的恢宏壮观——就像这幅画里的落日——而且创作时充满激情。"}}]},"examples":[{"en":"It was a performance of verve and vitality.","cn":"这是一场充满激情与活力的演出。"},{"en":"Cziffra played the Hungarian dances with great verve.","cn":"奇夫拉热情洋溢地演奏匈牙利舞曲。"}]},"vet":{"media":{"uk":"media/uk/vet__gb_1.mp3","us":"media/us/vet__us_1.mp3"},"oxford":{"phon":"vet","pos":"noun","senses":[{"en":"a person who has been trained in the science of animal medicine, whose job is to treat animals who are sick or injured","cn":"兽医","lab":"especially British English","ex":{"en":"We had to take the dog to the local vet.","cn":"我们只好带 狗去看当地的兽医。"}},{"en":"the place where a vet works","cn":"兽医诊所","ex":{"en":"I've got to take the dog to the vet's tomorrow.","cn":"明天我得把狗带到兽医诊所去诊治。"}},{"en":"a person who has been a soldier, sailor, etc. in a war","cn":"退伍军人；老兵；老战士；老水兵","lab":"North American English, informal，，","ex":{"en":"a Vietnam vet","cn":"参加过越战的老兵"}},{"en":"to find out about a person’s past life and career in order to decide if they are suitable for something","cn":"对（候选人）做背景调查","ex":{"en":"All candidates are carefully vetted for security reasons.","cn":"出于安全考虑，所有的求职申请人都要经过严格的审查。"},"pos":"verb"},{"en":"to check the contents, quality, etc. of something carefully","cn":"仔细检查，审查（内容、质量等）","ex":{"en":"All reports are vetted before publication.","cn":"所有报道都要经过仔细检查后才能发表。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"兽医","en":"A vet is someone who is qualified to treat sick or injured animals."},{"pos":"N-COUNT 可数名词","cn":"退伍军人;老兵;老战士","en":"A vet is someone who has served in the armed forces of their country, especially during a war.","ex":{"en":"The New England Shelter in Boston will serve Christmas dinner for 200 vets","cn":"波士顿的新英格兰收容所将为200名老兵提供圣诞晚餐。"}},{"pos":"VERB 动词","cn":"检查;审查","en":"If something is vetted, it is checked carefully to make sure that it is acceptable to people in authority.","ex":{"en":"He can find no trace of a rule requiring research to be vetted before publication","cn":"他找不到任何要求研究成果在发表前需经审查的规定。"}},{"pos":"VERB 动词","cn":"（尤指对将要从事涉及军事或政治机密工作人员的）调查，审查，考查","en":"If someone is vetted, they are investigated fully before being given a particular job, role, or position, especially one which involves military or political secrets.","ex":{"en":"She was secretly vetted before she ever undertook any work for me","cn":"她在为我工作以前曾受到过秘密考查。"}}]},"examples":[{"en":"All candidates are carefully vetted for security reasons.","cn":"由于安全的缘故，所有的求职申请人都要经过严格的审查。"},{"en":"All reports are vetted before publication.","cn":"所有报道都要经过仔细检查后才能发表。"}]},"vessels":{"oxford":{"phon":"ˈvesl","pos":"noun","senses":[{"en":"( formal ) a large ship or boat","cn":"大船；轮船"},{"en":"( old use or technical","cn":"术语 ) a container used for holding liquids, such as a bowl, cup, etc. （盛液体的）容器，器皿"}]},"media":{"uk":"media/uk/vessel__gb_1.mp3","us":"media/us/vessel__us_1.mp3"}},"verse":{"oxford":{"phon":"vɜːs","pos":"noun","senses":[{"en":"writing that is arranged in lines, often with a regular rhythm or pattern of rhyme","cn":"诗；韵文","g":"[uncountable]","ex":{"en":"Most of the play is written in verse, but some of it is in prose.","cn":"这个剧本大部分是用韵文写的，不过有一些是用散文。"}},{"en":"a group of lines that form a unit in a poem or song","cn":"诗节；歌曲的段落","g":"[countable]","ex":{"en":"a hymn with six verses","cn":"一首六节的赞美诗"}},{"en":"poetry","cn":"诗","g":"[plural]","lab":"old-fashioned","ex":{"en":"a book of comic verses","cn":"打油诗集"}},{"en":"any one of the short numbered divisions of a chapter in the Bible","cn":"（《圣经》的）节","g":"[countable]","ex":{"en":"She always read a few verses from the Bible before going to bed.","cn":"她总是在睡觉前读几节圣经。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"诗;诗体;韵文","en":"Verse is writing arranged in lines which have rhythm and which often rhyme at the end.","ex":{"en":"...a slim volume of verse","cn":"一本薄薄的诗集"}},{"pos":"N-COUNT 可数名词","cn":"诗节;诗行；（歌曲的）段落;（《圣经》、《古兰经》等中的）节","en":"A verse is one of the parts into which a poem, a song, or a chapter of the Bible or the Koran is divided.","ex":{"en":"This verse describes three signs of spring","cn":"这节诗描绘了春天来临的三个征兆。"}},{"pos":"","cn":"","en":"chapter and verse→see: ;"}]},"media":{"uk":"media/uk/verse__gb_1.mp3","us":"media/us/verse__us_1.mp3"},"examples":[{"en":"Most of the play is written in verse, but some of it is in prose.","cn":"这剧本大部分是用韵文写的，不过有一些是用散文。"},{"en":"a hymn with six verses","cn":"一首六节的赞美诗"}]},"veiled":{"media":{"uk":"media/uk/veiled__gb_1.mp3","us":"media/us/veiled__us_1.mp3"},"oxford":{"phon":"veɪld","pos":"adjective","senses":[{"en":"a veiled threat, warning, etc. is not expressed directly or clearly because you do not want your meaning to be too obvious","cn":"（威胁、警告等）含蓄的，掩饰的","ex":{"en":"a thinly veiled threat","cn":"几乎不加掩饰的威胁"}},{"en":"wearing a veil (= a piece of cloth worn to cover the face, hair, or head)","cn":"戴面纱的；蒙面的","ex":{"en":"Veiled women shop at the market.","cn":"戴面纱的妇女在市场购物。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"间接表示的;含蓄的;不明言的","en":"A veiled comment is expressed in a disguised form rather than directly and openly.","ex":{"en":"He made only a veiled reference to international concerns over human rights issues","cn":"他只是含蓄地提到了国际社会对人权问题的关注。"}},{"pos":"ADJ 形容词","cn":"蒙面纱的;戴面罩的","en":"A woman or girl who is veiled is wearing a veil.","ex":{"en":"A veiled woman gave me a kindly smile.","cn":"一位戴面纱的女士朝我友好地微笑。"}}]},"examples":[{"en":"She made a veiled reference to his past mistakes.","cn":"她含蓄地提到了他过去所犯的错误。"},{"en":"a thinly veiled threat","cn":"几乎不加掩饰的威胁"}]},"vegetation":{"media":{"uk":"media/uk/vegetation__gb_1.mp3","us":"media/us/vegetation__us_1.mp3"},"oxford":{"phon":"ˌvedʒəˈteɪʃn","pos":"noun","senses":[{"en":"plants in general, especially the plants that are found in a particular area or environment","cn":"（统称）植物；（尤指某地或环境的）植被，植物群落，草木","ex":{"en":"The hills are covered in lush green vegetation.","cn":"这片丘陵草木茂盛，郁郁葱葱。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"植被;植物;草木","en":"Plants, trees, and flowers can be referred to as vegetation .","ex":{"en":"The inn has a garden of semi-tropical vegetation.","cn":"这家小旅馆里有一个亚热带植物园。"}}]},"examples":[{"en":"The hills are covered in lush green vegetation.","cn":"这片丘岭草木茂盛，郁郁葱葱。"},{"en":"Lefkas has an abundance of lush green vegetation.","cn":"莱夫卡斯有葱郁茂盛的植被。"}]},"vendetta":{"media":{"uk":"media/uk/vendetta__gb_1.mp3","us":"media/us/vendetta__us_1.mp3"},"oxford":{"phon":"venˈdetə","pos":"noun","senses":[{"en":"a long period of violence between two families or groups, in which people are murdered in return for previous murders","cn":"家族世仇；团伙仇杀"},{"en":"a long argument or campaign in which one person or group does or says things to harm another","cn":"积怨；宿怨；长期不和","ex":{"en":"He has accused the media of pursuing a vendetta against him.","cn":"他指责媒体长期跟他过不去。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"宿怨;积怨","en":"If one person has a vendetta against another, the first person wants revenge for something the second person did to them in the past.","ex":{"en":"The vice president said the cartoonist has a personal vendetta against him","cn":"副总裁说那个漫画家和他有私怨。"}}]},"examples":[{"en":"He has accused the media of pursuing a vendetta against him.","cn":"他指责媒体长期跟他过不去。"},{"en":"She conducted a personal vendetta against me.","cn":"她对我有宿仇。"}]},"vehicle":{"media":{"uk":"media/uk/vehicle__gb_1.mp3","us":"media/us/vehicle__us_1.mp3"},"oxford":{"phon":"ˈviːəkl","pos":"noun","senses":[{"en":"a thing that is used for transporting people or goods from one place to another, such as a car or lorry","cn":"交通工具；车辆","lab":"rather formal","ex":{"en":"motor vehicles (= cars, buses, lorries, etc.)","cn":"机动车辆"}},{"en":"something that can be used to express your ideas or feelings, or as a way of achieving something","cn":"（赖以表达思想、感情或达到目的的）手段，工具","ex":{"en":"Art may be used as a vehicle for propaganda.","cn":"艺术可以用作宣传的工具。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"车辆;交通工具;运输工具","en":"A vehicle is a machine such as a car, bus, or truck which has an engine and is used to carry people from place to place.","ex":{"en":"The vehicle would not have the capacity to make the journey on one tank of fuel.","cn":"这辆车单靠一箱燃料无法跑完整趟旅程。"}},{"pos":"N-COUNT 可数名词","cn":"（实现目的的）工具，手段,媒介","en":"You can use vehicle to refer to something that you use in order to achieve a particular purpose.","ex":{"en":"Her art became a vehicle for her political beliefs","cn":"艺术成了她表达政治信仰的工具。"}}]},"examples":[{"en":"The play is an ideal vehicle for her talents.","cn":"这部戏是她施展才华的理想机会。"},{"en":"Are you the driver of this vehicle?","cn":"你是这辆汽车的驾驶员吗？"}]},"vessel":{"media":{"uk":"media/uk/vessel__gb_1.mp3","us":"media/us/vessel__us_1.mp3"},"oxford":{"phon":"ˈvesl","pos":"noun","senses":[{"en":"a tube that carries blood through the body of a person or an animal, or liquid through the parts of a plant","cn":"（人或动物的）血管，脉管；（植物的）导管","ex":{"en":"to burst/rupture a blood vessel","cn":"使血管破裂"}},{"en":"a ship or large boat","cn":"轮船；大船","lab":"formal","ex":{"en":"ocean-going vessels","cn":"远洋轮船"}},{"en":"a container used for holding liquids, such as a bowl, cup, etc.","cn":"（盛液体的）容器，器皿","lab":"old use or specialist","ex":{"en":"a Bronze Age drinking vessel","cn":"青铜器时代的饮具"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"舰;轮船;大船","en":"A vessel is a ship or large boat.","ex":{"en":"A Moroccan fishing vessel and a South Korean cargo ship collided in rough seas.","cn":"一艘摩洛哥渔船与一艘韩国货船在波涛汹涌的大海上相撞了。"}},{"pos":"N-COUNT 可数名词","cn":"（盛液体用的）容器，器皿","en":"A vessel is a bowl or other container in which liquid is kept.","ex":{"en":"He makes decorative vessels in copper, stainless steel and silver.","cn":"他用铜、不锈钢和银制造装饰性器皿。"}}]},"examples":[{"en":"a Bronze Age drinking vessel","cn":"青铜器时代的饮具"},{"en":"ocean-going vessels","cn":"远洋轮船"}]},"vermilion":{"media":{"uk":"media/uk/vermilion__gb_1.mp3","us":"media/us/vermilion__us_1.mp3"},"oxford":{"phon":"vəˈmɪliən","pos":"adjective","senses":[{"en":"bright red in colour","cn":"鲜红的；朱红的"},{"en":"a bright red colour","cn":"樱桃色；鲜红色；朱红色","ex":{"en":"As the sun set, the clouds were streaked with vermilion.","cn":"夕阳西下，云彩染上朱红色。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"鲜红(色);朱红(色)","en":"Vermilion is used to describe things that are bright red in colour.","ex":{"en":"...her vermilion lip gloss","cn":"她鲜红色的唇彩"}}]}},"velvet":{"media":{"uk":"media/uk/velvet__gb_1.mp3","us":"media/us/velvet__us_1.mp3"},"oxford":{"phon":"ˈvelvɪt","pos":"noun","senses":[{"en":"a type of cloth made from silk, cotton or nylon, with a thick, soft surface","cn":"丝绒；立绒；经绒；天鹅绒","ex":{"en":"a velvet dress","cn":"天鹅绒连衣裙"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"丝绒;天鹅绒","en":"Velvet is soft material made from cotton, silk, or nylon, which has a thick layer of short cut threads on one side.","ex":{"en":"...a charcoal-gray overcoat with a velvet collar","cn":"带天鹅绒领子的炭灰色外套"}}]},"examples":[{"en":"velvet curtains/drapes","cn":"天鹅绒窗帘/帷幕"},{"en":"a velvet dress","cn":"天鹅绒连衣裙"}]},"veranda":{"media":{"uk":"media/uk/veranda__gb_1.mp3","us":"media/us/veranda__us_1.mp3"},"oxford":{"phon":"vəˈrændə","pos":"noun","senses":[{"en":"a platform with an open front and a roof, built onto the side of a house on the ground floor","cn":"（房屋底层有顶半敞的）走廊，游廊","lab":"especially British English","ex":{"en":"After dinner, we sat talking on the veranda.","cn":"饭后我们坐在游廊上交谈。"}},{"en":"a roof over the part of the street where people walk in front of a shop","cn":"（店铺面街上方的）遮檐","lab":"Australian English, New Zealand English，，"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（房屋外带屋顶的）走廊，游廊,阳台","en":"A veranda is a roofed platform along the outside of a house.","ex":{"en":"They had their coffee and tea on the veranda.","cn":"他们在阳台上喝咖啡和茶。"}}]},"examples":[{"en":"After dinner, we sat talking on the veranda.","cn":"饭后我们坐在游廊上交谈。"}]},"veggie":{"media":{"uk":"media/uk/veggie__gb_1.mp3","us":"media/us/veggie__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"同vegetarian","en":"Veggie means the same as vegetarian .","ex":{"en":"You can cook a cheap veggie chilli in 15 minutes","cn":"你可以在15分钟内做出一道便宜的辣椒素菜。"}},{"pos":"N-COUNT 可数名词","cn":"蔬菜","en":"Veggies are plants such as cabbages, potatoes, and onions which you can cook and eat.","ex":{"en":"...well-balanced meals of fresh fruit and veggies, chicken, fish, pasta, and no red meat.","cn":"包含新鲜水果和蔬菜、鸡肉、鱼肉、意大利面，不含红色肉类的搭配均衡的饮食"}}]},"examples":[{"en":"He's turned veggie (= become a vegetarian ).","cn":"他改吃素了。"},{"en":"fresh veggies","cn":"新鲜蔬菜"}],"oxford":{"phon":"ˈvedʒi","pos":"adjective","senses":[{"en":"eating no meat or fish; containing or serving no meat or fish","cn":"吃素的，素食的","ex":{"en":"I've been veggie for years.","cn":"我已经吃素很多年了。"}},{"en":"a vegetarian (= a person who does not eat meat or fish)","cn":"素食者","ex":{"en":"He's turned veggie (= become a vegetarian).","cn":"他改吃素了。"},"pos":"noun"},{"en":"a vegetable","cn":"蔬菜","lab":"especially North American English","pos":"noun"}]}},"veil":{"oxford":{"phon":"veɪl","pos":"noun","senses":[{"en":"a piece of very thin material, worn especially by women to protect or hide the face, or as part of a hat, etc.","cn":"（尤指女用的）面纱，面罩","ex":{"en":"The bridal veil was fringed with lace.","cn":"新娘戴的面纱上镶着花边。"}},{"en":"a piece of cloth worn over the head and shoulders by nuns or Muslim women","cn":"（修女或穆斯林妇女的）头巾"},{"en":"something that stops you from learning the truth about a situation","cn":"掩饰；掩盖；借口；托辞","g":"[singular]","lab":"formal","ex":{"en":"Their work is carried out behind a veil of secrecy.","cn":"他们的工作是在秘密掩护下进行的。"}},{"en":"a thin layer that stops you from seeing something","cn":"薄薄的遮盖层","g":"[singular]","lab":"formal","ex":{"en":"The mountain tops were hidden beneath a veil of mist.","cn":"山顶笼罩在薄雾中。"}},{"en":"to cover your face with a veil","cn":"戴面纱；戴面罩","pos":"verb"},{"en":"to cover something with something that hides it partly or completely","cn":"遮掩；掩饰","lab":"literary","ex":{"en":"A fine drizzle began to veil the hills.","cn":"蒙蒙的细雨渐渐笼罩了群山。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"面纱;面罩","en":"A veil is a piece of thin soft cloth that women sometimes wear over their heads and which can also cover their face.","ex":{"en":"She's got long fair hair but she's got a veil over it","cn":"她有一头金色的长发，但她用头巾包住了。"}},{"pos":"N-COUNT 可数名词","cn":"掩盖物;遮蔽物","en":"You can refer to something that hides or partly hides a situation or activity as a veil .","ex":{"en":"The country is ridding itself of its disgraced prime minister in a veil of secrecy","cn":"这个国家暗地里正试图把失势的首相赶下台。"}},{"pos":"N-COUNT 可数名词","cn":"（薄雾等）幕障","en":"You can refer to something that you can partly see through, for example a mist, as a veil.","ex":{"en":"The eruption has left a thin veil of dust in the upper atmosphere","cn":"火山爆发在高层大气中留下了一层薄薄的尘土。"}},{"pos":"PHRASE 短语","cn":"隐瞒;避而不谈","en":"If you draw a veil over something, you stop talking about it because it is too unpleasant to talk about.","ex":{"en":"The clamour to draw a veil over the minister's extra-marital activities reeks of hypocrisy.","cn":"想要掩饰部长婚外情的喧嚣叫嚷之声让人倍感虚伪。"}}]},"media":{"uk":"media/uk/veil__gb_1.mp3","us":"media/us/veil__us_1.mp3"},"examples":[{"en":"Their work is carried out behind a veil of secrecy.","cn":"他们的工作是在秘密掩护下进行的。"},{"en":"It would be better to draw a veil over what happened next (= not talk about it).","cn":"最好把之后发生的事情掩盖起来。"}]},"vent":{"oxford":{"phon":"vent","pos":"noun","senses":[{"en":"an opening that allows air, gas or liquid to pass out of or into a room, building, container, etc.","cn":"（空气、气体、液体的）出口，进口，漏孔","ex":{"en":"air/heating vents","cn":"通气孔；热风孔"}},{"en":"the opening in the body of a bird, fish, reptile or other small animal, through which waste matter is passed out","cn":"（鸟、鱼等小动物的）肛门","lab":"specialist"},{"en":"a long, thin opening at the bottom of the back or side of a coat or jacket","cn":"（大衣等的）衩口，开衩，背衩"},{"en":"to express feelings, especially anger, strongly","cn":"表达，发泄（感情，尤指愤怒）","ex":{"en":"He vented his anger on the referee.","cn":"他把气撒在裁判身上。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"通风孔;排气口","en":"A vent is a hole in something through which air can come in and smoke, gas, or smells can go out.","ex":{"en":"Quite a lot of steam escaped from the vent at the front of the machine","cn":"大量蒸汽从机器前部的排风口冒了出来。"}},{"pos":"VERB 动词","cn":"发泄,宣泄（情感）","en":"If you vent your feelings, you express them forcefully.","ex":{"en":"She telephoned her best friend to vent her frustration","cn":"她给最要好的朋友打电话倾诉自己的沮丧。"}},{"pos":"PHRASE 短语","cn":"发泄,宣泄（情感）","en":"If you give vent to your feelings, you express them forcefully.","ex":{"en":"She gave vent to her anger and jealousy.","cn":"她宣泄了自己的愤怒和嫉妒。"}},{"pos":"PHRASE 短语","cn":"（尤指突然地或作为回应）发出（声音）","en":"If you give vent to a noise, you make a particular type of noise, especially suddenly or as a reaction to something.","ex":{"en":"He squatted on the floor and gave vent to a deep sigh","cn":"他蹲在地板上，深深叹了一口气。"}}]},"media":{"uk":"media/uk/vent__gb_1.mp3","us":"media/us/vent__us_1.mp3"},"examples":[{"en":"She gave full vent to her feelings in a violent outburst.","cn":"她大发脾气以宣泄情绪。"},{"en":"He vented his anger on the referee.","cn":"他把气撒在裁判身上。"}]},"vehemently":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"showing very strong feelings or opinions","cn":""},{"en":"vehement opposition/criticism/hostility etc Despite vehement opposition, the Act became law. Despite her vehement protests, he pulled her inside.","cn":""}]},"media":{"uk":"media/uk/vehemently__gb_1.mp3","us":"media/us/vehemently__us_1.mp3"},"oxford":{"phon":"ˈviːəməntli","pos":"adverb","senses":[{"en":"in a way that shows very strong feelings, especially anger","cn":"（感情）强烈的，激烈的；（尤指）愤怒的","ex":{"en":"The charge was vehemently denied.","cn":"这项指控被断然否认了。"}}]}},"venture":{"media":{"uk":"media/uk/venture__gb_1.mp3","us":"media/us/venture__us_1.mp3"},"oxford":{"phon":"ˈventʃə(r)","pos":"noun","senses":[{"en":"a business project or activity, especially one that involves taking risks","cn":"（尤指有风险的）企业，商业，投机活动，经营项目","ex":{"en":"A disastrous business venture lost him thousands of dollars.","cn":"一个彻底失败的经营项目使他损失成千上万美元。"}},{"en":"to go somewhere even though you know that it might be dangerous or unpleasant","cn":"敢于去（危险或令人不快的地方）","g":"[intransitive]","ex":{"en":"They ventured nervously into the water.","cn":"他们紧张地硬着头皮下水。"},"pos":"verb"},{"en":"to say or do something in a careful way, especially because it might upset or offend somebody","cn":"小心地说，谨慎地做（尤指会使人烦恼或不快的事）","g":"[transitive]","lab":"formal","ex":{"en":"She hardly dared to venture an opinion.","cn":"她几乎不敢亮明观点。"},"pos":"verb"},{"en":"to risk losing something valuable or important if you are not successful at something","cn":"冒着（失去贵重或重要的东西）的危险","g":"[transitive]","ex":{"en":"It was wrong to venture his financial security on such a risky deal.","cn":"他牺牲自己的财务安全去做风险这么大的交易是错误的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"风险项目（或活动);冒险事业","en":"A venture is a project or activity which is new, exciting, and difficult because it involves the risk of failure.","ex":{"en":"...his latest writing venture.","cn":"他最新的写作尝试"}},{"pos":"VERB 动词","cn":"冒险去（某处）","en":"If you venture somewhere, you go somewhere that might be dangerous.","ex":{"en":"People are afraid to venture out for fear of sniper attacks","cn":"由于害怕狙击手，人们不敢冒险外出。"}},{"pos":"VERB 动词","cn":"斗胆提出（问题）;冒险发表（陈述）","en":"If you venture a question or statement, you say it in an uncertain way because you are afraid it might be stupid or wrong.","ex":{"en":"'So you're Leo's girlfriend?' he ventured","cn":"“那么你就是列奥的女朋友了？”他大胆问道。"}},{"pos":"VERB 动词","cn":"勇于做;冒险做","en":"If you venture to do something that requires courage or is risky, you do it.","ex":{"en":"'Don't ask,' he said, whenever Ginny ventured to raise the subject.","cn":"每当金尼鼓起勇气提起这个话题时，他就说“不要问”。"}},{"pos":"VERB 动词","cn":"冒险尝试","en":"If you venture into an activity, you do something that involves the risk of failure because it is new and different.","ex":{"en":"He enjoyed little success when he ventured into business.","cn":"他冒险涉足商界后几乎没有取得什么成功。"}}]},"examples":[{"en":"It was wrong to venture his financial security on such a risky deal.","cn":"他以自己稳定的财政作赌注去做风险这么大的交易是错误的。"},{"en":"A disastrous business venture lost him thousands of dollars.","cn":"一个彻底失败的经营项目使他损失严重。"}]},"versus":{"oxford":{"phon":"ˈvɜːsəs","pos":"preposition","senses":[{"en":"used to show that two teams or sides are against each other","cn":"（表示两队或双方对阵）对，诉，对抗","lab":"sport or law","ex":{"en":"It is France versus Brazil in the final.","cn":"决赛是法国队对巴西队。"}},{"en":"used to compare two different ideas, choices, etc.","cn":"（比较两种不同想法、选择等）与…相对，与…相比","ex":{"en":"It was the promise of better job opportunities versus the inconvenience of moving away and leaving her friends.","cn":"可能会有较好的就业前景，但麻烦的是要搬走并远离她的朋友。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"与…相对;与…相比","en":"You use versus to indicate that two figures, ideas, or choices are opposed.","ex":{"en":"Only 18.8% of the class of 1982 had some kind of diploma four years after high school, versus 45% of the class of 1972.","cn":"1982年那一届只有18.8% 的学生在中学毕业4年后获得了某种文凭，而1972年那一届这一比例是45％。"}},{"pos":"PREP 介词","cn":"（体育比赛中）与…对阵，与…竞争","en":"Versus is used to indicate that two teams or people are competing against each other in a sporting event.","ex":{"en":"Italy versus Japan is turning out to be a surprisingly well matched competition.","cn":"在意大利队对日本队的比赛中，双方竟出人意料地势均力敌。"}}]},"media":{"uk":"media/uk/versus__gb_1.mp3","us":"media/us/versus__us_1.mp3"},"examples":[{"en":"It was the promise of better job opportunities versus the inconvenience of moving away and leaving her friends.","cn":"那是较好的就业前景与搬走并远离朋友的不便之间的矛盾。"},{"en":"in the case of the State versus Ford","cn":"在州政府诉福特公司的案件中"}]},"vertical":{"media":{"uk":"media/uk/vertical__gb_1.mp3","us":"media/us/vertical__us_1.mp3"},"oxford":{"phon":"ˈvɜːtɪkl","pos":"adjective","senses":[{"en":"going straight up or down from a level surface or from top to bottom in a picture, etc.","cn":"竖的；垂直的；直立的","ex":{"en":"the vertical axis of the graph","cn":"图的纵轴"}},{"en":"having a structure in which there are top, middle and bottom levels","cn":"纵向的","ex":{"en":"a vertical flow of communication","cn":"上下级纵向交流"}},{"en":"passed from one generation to the next","cn":"代代相传","lab":"medical","ex":{"en":"4% of these infections result from vertical transmission from mother to baby.","cn":"这些感染中有4%是由母婴垂直传播造成的。"}},{"en":"a straight line or position from top to bottom or bottom to top","cn":"竖直线；垂直位置","ex":{"en":"The wall is several degrees off the vertical.","cn":"这堵墙倾斜了有好几度。"},"pos":"noun"},{"en":"an area of business or field of activity","cn":"垂直行业","lab":"business","ex":{"en":"This year we saw significant growth outside our core verticals.","cn":"今年，我们在核心垂直领域之外看到了显着增长。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"垂直的;直立的","en":"Something that is vertical stands or points straight up.","ex":{"en":"The climber inched up a vertical wall of rock","cn":"攀登者慢慢爬上了陡直的石壁。"}},{"pos":"N-SING 单数名词","cn":"垂直方向","en":"The vertical is the direction that points straight up, at an angle of 90 degrees to a flat surface.","ex":{"en":"Pluto seems to have suffered a major collision that tipped it 122 degrees from the vertical.","cn":"冥王星似乎受到过严重撞击，倾斜了122度。"}},{"pos":"N-COUNT 可数名词","cn":"垂直线;垂直面","en":"A vertical is a line or structure that is vertical.","ex":{"en":"As long as the verticals align, the design will look regular.","cn":"只要所有垂直面在一条线上，图案看起来就会很整齐。"}}]},"examples":[{"en":"There was a vertical drop to the ocean.","cn":"至海洋有一段垂直落差。"},{"en":"The wall is several degrees off the vertical.","cn":"这堵墙倾斜了有好几度。"}]},"vegetable":{"media":{"img":["media/pic/vegetables_garlic_comp.jpg","media/thumb/corn.jpg"],"uk":"media/uk/vegetable__gb_1.mp3","us":"media/us/vegetable__us_1.mp3"},"oxford":{"phon":"ˈvedʒtəbl","pos":"noun","senses":[{"en":"a plant or part of a plant that is eaten as food. Potatoes, beans and onions are all vegetables.","cn":"蔬菜","lab":"also especially North American English, informal，，","ex":{"en":"The children don't eat enough fresh vegetables.","cn":"孩子们新鲜蔬菜吃得不够。"}},{"en":"an offensive word for a person who is physically alive but not capable of much mental or physical activity, for example because of a serious accident or illness","cn":"植物人","lab":"offensive"},{"en":"a person who has a boring life","cn":"生活单调乏味的人","ex":{"en":"Since losing my job I've been a vegetable.","cn":"失业以来我感到百无聊赖。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蔬菜","en":"Vegetables are plants such as cabbages, potatoes, and onions which you can cook and eat.","ex":{"en":"A good general diet should include plenty of fresh vegetables.","cn":"良好的日常饮食应该包含大量的新鲜蔬菜。"}},{"pos":"ADJ 形容词","cn":"蔬菜的;植物的","en":"Vegetable matter comes from plants.","ex":{"en":"...compounds, of animal, vegetable or mineral origin.","cn":"动物源性、植物源性或矿物源性的化合物"}},{"pos":"N-COUNT 可数名词","cn":"植物人","en":"If someone refers to a brain-damaged person as a vegetable, they mean that the person cannot move, think, or speak."}]},"examples":[{"en":"Severe brain damage turned him into a vegetable.","cn":"严重的脑损伤使他变成了植物人。"},{"en":"Since losing my job I've been a vegetable.","cn":"失业以来我感到百无聊赖。"}]},"venting":{"oxford":{"phon":"vent","pos":"noun","senses":[{"en":"an opening that allows air, gas or liquid to pass out of or into a room, building, container, etc. （","cn":"空气、气体、液体的）出口，进口，漏孔"},{"en":"( technical","cn":"术语 ) the opening in the body of a bird, fish, reptile or other small animal, through which waste matter is passed out （鸟"}]}},"very":{"media":{"uk":"media/uk/very__gb_1.mp3","us":"media/us/very__us_1.mp3"},"oxford":{"phon":"ˈveri","pos":"adverb","senses":[{"en":"used before adjectives, adverbs and determiners to mean ‘in a high degree’ or ‘extremely’","cn":"（置于形容词、副词和限定词前）很，非常，十分，极","ex":{"en":"Very few people know that.","cn":"很少有人知道那件事。"}},{"en":"used to emphasize a superlative adjective or before own","cn":"（强调形容词最高级或置于 own 前）完全，十足","ex":{"en":"They wanted the very best quality.","cn":"他们要最好的质量。"}},{"en":"exactly the same","cn":"完全同样；完全同一","ex":{"en":"Mario said the very same thing.","cn":"马里奥说过一模一样的话。"}},{"en":"used to emphasize that you are talking about a particular thing or person and not about another","cn":"（特指人或事物）正是的，恰好的，同一的","ex":{"en":"He might be phoning her at this very moment.","cn":"他也许这会儿正在给她打电话呢。"},"pos":"adjective"},{"en":"used to emphasize an extreme place or time","cn":"（强调极限的地点或时间）最…的，极端的，十足的","ex":{"en":"It happens at the very beginning of the book.","cn":"这事发生在书的一开头。"},"pos":"adjective"},{"en":"used to emphasize a noun","cn":"（加强名词的语气）仅仅的，唯独的，甚至于","ex":{"en":"The very nature of its business is to secretly monitor and profile internet users' habits.","cn":"其业务本质就是秘密监控并概述互联网用户的习惯。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"很，非常（用于修饰形容词或副词，表示强调）","en":"Very is used to give emphasis to an adjective or adverb.","ex":{"en":"The problem and the answer are very simple","cn":"问题和答案都非常简单。"}},{"pos":"PHRASE 短语","cn":"绝不；远非；不太；稍微","en":"Not very is used with an adjective or adverb to say that something is not at all true, or that it is true only to a small degree.","ex":{"en":"She's not very impressed with them","cn":"她对他们没什么印象。"}},{"pos":"ADV 副词","cn":"显然;确实;真正地","en":"You use very to give emphasis to an adjective that is not usually graded, when you want to say that a quality is very obvious.","ex":{"en":"Janet looked very pregnant","cn":"珍妮特看上去显然是怀孕了。"}},{"pos":"ADV 副词","cn":"完全，最（用于修饰形容词或副词最高级,表示强调）","en":"You use very to give emphasis to a superlative adjective or adverb. For example, if you say that something is the very best, you are emphasizing that it is the best.","ex":{"en":"They will be helped by the very latest in navigation aids","cn":"他们将会受益于最新的导航系统。"}},{"pos":"ADJ 形容词","cn":"（与某些名词连用，以确指最远的某一位置或时点）极端的","en":"You use very with certain nouns in order to specify an extreme position or extreme point in time.","ex":{"en":"At the very back of the yard, several feet from Lenny, was a wooden shack","cn":"在院子的最后面离伦尼几英尺远的地方有一个小木屋。"}},{"pos":"ADJ 形容词","cn":"正是的;合适的;同样的","en":"You use very with nouns to emphasize that something is exactly the right one or exactly the same one.","ex":{"en":"Everybody says he is the very man for the case","cn":"每个人都说他是接手这个案子的最佳人选。"}},{"pos":"ADJ 形容词","cn":"（与名词连用，强调重要性或严重性）仅仅的，唯独的，甚至于，就连","en":"You use very with nouns to emphasize the importance or seriousness of what you are saying.","ex":{"en":"At one stage his very life was in danger","cn":"他的生命都曾一度处于危险之中。"}},{"pos":"CONVENTION 惯用语","cn":"好的，是（用于表示对上级的指示或命令遵照执行）","en":"Very good is used to tell someone in authority that you agree to carry out a suggestion or order.","ex":{"en":"'Now give me some account of your voyage.' — 'Very good, sir.'","cn":"“现在给我讲述一下你的航程吧。”——“非常乐意，先生。”"}},{"pos":"PHRASE 短语","cn":"的确如此;千真万确","en":"The expression very much so is an emphatic way of answering 'yes' to something or saying that it is true or correct.","ex":{"en":"'Are you enjoying your holiday?' — 'Very much so.'","cn":"“你的假期过得愉快吗？”——“非常愉快。”"}},{"pos":"CONVENTION 惯用语","cn":"那好吧，行（用于表示同意或接受，即使不是完全满意）","en":"Very well is used to say that you agree to do something or you accept someone's answer, even though you might not be completely satisfied with it.","ex":{"en":"'We need proof, sir.' Another pause. Then, 'Very well.'","cn":"“我们需要证据，先生。”又是一个短暂停顿。然后，“那好吧。”"}},{"pos":"PHRASE 短语","cn":"不好，不能，没法（做…）","en":"If you say that you cannot very well do something, you mean that it would not be right or possible to do it.","ex":{"en":"He couldn't very well go to her office and force her to write a check","cn":"他不能去她的办公室强迫她开支票。"}}]},"examples":[{"en":"‘I can't do that!’ she gasped, appalled at the very idea. “","cn":"那事我可不能干！”她一听到这个想法便吃惊地倒抽着冷气。"},{"en":"‘Is it what you expected?’ ‘Oh yes, very much so. ’ “","cn":"这是你所期望的吗？” “啊，是的，非常期望如此。”"}]},"verb":{"media":{"uk":"media/uk/verb__gb_1.mp3","us":"media/us/verb__us_1.mp3"},"oxford":{"phon":"vɜːb","pos":"noun","senses":[{"en":"a word or group of words that expresses an action (such as eat), an event (such as happen) or a state (such as exist)","cn":"动词","ex":{"en":"regular/irregular verbs","cn":"规则／不规则动词"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"动词","en":"A verb is a word such as 'sing', 'feel', or 'die' which is used with a subject to say what someone or something does or what happens to them, or to give information about them."}]},"examples":[{"en":"regular/irregular verbs","cn":"规则/不规则动词"},{"en":"transitive/intransitive verbs","cn":"及物/不及物动词"}]},"vend":{"oxford":{"phon":"vend","pos":"verb","senses":[{"en":"to sell something","cn":"售卖"}]},"media":{"uk":"media/uk/vend__gb_1.mp3","us":"media/us/vend__us_1.mp3"}},"version":{"media":{"uk":"media/uk/version__gb_1.mp3","us":"media/us/version__us_1.mp3"},"oxford":{"phon":"ˈvɜːʃn","pos":"noun","senses":[{"en":"a form of something that is slightly different from an earlier form or from other forms of the same thing","cn":"变体；变种；型式","ex":{"en":"the latest version of the software package","cn":"软件包的最新版本"}},{"en":"a film, play, piece of music, etc. that is based on a particular piece of work but is in a different form, style or language","cn":"（电影、剧本、乐曲等的）版本，改编形式，改写本","ex":{"en":"the film version of ‘War and Peace’","cn":"根据《战争与和平》改编的电影"}},{"en":"a description of an event from the point of view of a particular person or group of people","cn":"（从不同角度的）说法，描述","ex":{"en":"We have no way of knowing which version is true.","cn":"我们无法知道哪个版本是真实的。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"变化形式;变体;版本","en":"A version of something is a particular form of it in which some details are different from earlier or later forms.","ex":{"en":"...an updated version of his book","cn":"他的书的最新版本"}},{"pos":"N-COUNT 可数名词","cn":"（某人对某事件区别于他人的）描述，说法","en":"Someone's version of an event is their own description of it, especially when it is different to other people's.","ex":{"en":"Yesterday afternoon the White House put out a new version of events","cn":"昨天下午，白宫对事件给出了另一种说法。"}}]},"examples":[{"en":"She gave us her version of what had happened that day.","cn":"她向我们描述了她认为那天发生的事情。"},{"en":"Their versions of how the accident happened conflict.","cn":"他们对事故发生情况的说法相互矛盾。"}]},"vest":{"oxford":{"phon":"vest","pos":"noun","senses":[{"en":"a piece of underwear worn under a shirt, etc. next to the skin","cn":"（衬衣等里面贴身穿的）背心，汗衫","lab":"British English","ex":{"en":"a cotton vest","cn":"棉汗衫"}},{"en":"a special piece of clothing that covers the upper part of the body","cn":"坎肩；（外面穿的）背心","ex":{"en":"a bullet-proof vest","cn":"防弹背心"}},{"en":"a short piece of clothing with buttons down the front but no arms, usually worn over a shirt and under a jacket, often forming part of a formal suit","cn":"（西服的）背心","lab":"North American English","ex":{"en":"wearing jeans and a leather vest","cn":"穿着牛仔裤和皮背心"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"贴身背心;汗衫","en":"A vest is a piece of underwear which you can wear on the top half of your body in order to keep warm."},{"pos":"N-COUNT 可数名词","cn":"背心;马甲;坎肩","en":"A vest is a sleeveless piece of clothing with buttons which people usually wear over a shirt."},{"pos":"VERB 动词","cn":"授予，赋予，给予（权利或责任）","en":"If something is vested in you, or if you are vested with it, it is given to you as a right or responsibility.","ex":{"en":"All authority was vested in the woman, who discharged every kind of public duty","cn":"女性被赋予了所有权力，履行所有公共职责。"}}]},"media":{"img":["media/pic/clothes_suit_comp.jpg","media/thumb/patternedwaistcoat.jpg"],"uk":"media/uk/vest__gb_1.mp3","us":"media/us/vest__us_1.mp3"},"examples":[{"en":"Overall authority is vested in the Supreme Council.","cn":"一切权力属于最高议会。"},{"en":"The Supreme Council is vested with overall authority.","cn":"最高议会拥有一切权力。"}]},"vegetables":{"oxford":{"phon":"ˈvedʒtəbl","pos":"noun","senses":[{"en":"a plant or part of a plant that is eaten as food. Potatoes, beans and onions are all vegetables.","cn":"蔬菜"},{"en":"a person who is physically alive but not capable of much mental or physical activity, for example because of an accident or illness","cn":"植物人"}]},"media":{"img":["media/pic/vegetables_garlic_comp.jpg","media/thumb/corn.jpg"],"uk":"media/uk/vegetable__gb_1.mp3","us":"media/us/vegetable__us_1.mp3"}},"veteran":{"media":{"uk":"media/uk/veteran__gb_1.mp3","us":"media/us/veteran__us_1.mp3"},"oxford":{"phon":"ˈvetərən","pos":"noun","senses":[{"en":"a person who has a lot of experience in a particular area or activity","cn":"经验丰富的人；老手","ex":{"en":"the veteran American actor, Clint Eastwood","cn":"美国资深演员克林特·伊斯特伍德"}},{"en":"a person who has been a soldier, sailor, etc. in a war","cn":"退伍军人；老兵；老战士；老水兵","lab":"also North American English, informal，，","ex":{"en":"war veterans","cn":"经历过战争的老战士"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"退伍军人;老兵;老战士","en":"A veteran is someone who has served in the armed forces of their country, especially during a war.","ex":{"en":"They approved a $1.1 billion package of pay increases for the veterans of the Persian Gulf War.","cn":"他们通过了对参加过波斯湾战争的老兵增发共计11亿美元的一揽子提案。"}},{"pos":"N-COUNT 可数名词","cn":"有经验的人;老手","en":"You use veteran to refer to someone who has been involved in a particular activity for a long time.","ex":{"en":"...Tony Benn, the veteran Labour MP and former Cabinet minister.","cn":"托尼·本，一位经验丰富的工党下院议员和前内阁部长"}}]},"examples":[{"en":"the veteran American actor, Clint Eastwood","cn":"美国资深演员克林特 · 伊斯特伍德"},{"en":"war veterans","cn":"经历过战争的老战士"}]},"vegetarian":{"oxford":{"phon":"ˌvedʒəˈteəriən","pos":"noun","senses":[{"en":"a person who does not eat meat or fish","cn":"素食者；吃素的人","ex":{"en":"Is she a vegetarian?","cn":"她是素食者吗？"}},{"en":"eating no meat or fish","cn":"素食的；吃素的","ex":{"en":"Are you vegetarian?","cn":"你是素食者吗？"},"pos":"adjective"},{"en":"containing or serving no meat or fish","cn":"素食者；吃素的人","ex":{"en":"a vegetarian diet","cn":"素食食谱"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"吃素的;素食的","en":"Someone who is vegetarian never eats meat or fish.","ex":{"en":"Yasmin sticks to a strict vegetarian diet","cn":"亚斯明坚持不沾一点儿荤腥。"}},{"pos":"ADJ 形容词","cn":"无肉的;素的","en":"Vegetarian food does not contain any meat or fish.","ex":{"en":"...vegetarian lasagnes.","cn":"素卤汁宽面"}}]},"media":{"uk":"media/uk/vegetarian__gb_1.mp3","us":"media/us/vegetarian__us_1.mp3"},"examples":[{"en":"Is she a vegetarian?","cn":"她是素食者吗？"},{"en":"Are you vegetarian?","cn":"你只吃素食吗？"}]},"vermin":{"media":{"uk":"media/uk/vermin__gb_1.mp3","us":"media/us/vermin__us_1.mp3"},"oxford":{"phon":"ˈvɜːmɪn","pos":"noun","senses":[{"en":"wild animals or birds that destroy plants or food, or attack farm animals and birds","cn":"害兽；害鸟","ex":{"en":"On farms the fox is considered vermin and treated as such.","cn":"在农场里狐狸被当成有害动物来对待。"}},{"en":"insects that live on the bodies of animals and sometimes humans","cn":"体外寄生虫；害虫","ex":{"en":"The room was crawling with vermin.","cn":"这房间里虱蚤横行。"}},{"en":"people who are very unpleasant or dangerous to society","cn":"蟊贼；歹徒；害人虫","lab":"disapproving"}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"（对人类）有害的动物;害兽;害虫","en":"Vermin are small animals such as rats and mice which cause problems to humans by carrying disease and damaging crops or food.","ex":{"en":"From 1066 to the 17th century the fox was looked upon as vermin.","cn":"从1066年到17世纪，狐狸一直被视为害兽。"}}]},"examples":[{"en":"On farms the fox is considered vermin and treated as such.","cn":"在农场里狐狸被当成有害动物来对待。"},{"en":"The room was crawling with vermin.","cn":"这房间里虱蚤横行。"}]},"verandas":{"oxford":{"phon":"vəˈrændə","pos":"noun","senses":[{"en":"a platform with an open front and a roof, built onto the side of a house on the ground floor （","cn":"房屋底层有顶半敞的）走廊，游廊"},{"en":"( AustralE, NZE ) a roof over the part of the street where people walk in front of a shop/store （","cn":"店铺面街上方的）遮檐，游廊"}]}},"venerated":{"oxford":{"phon":"ˈvenəreɪt","pos":"verb","senses":[{"en":"( formal ) to have and show a lot of respect for sb/sth, especially sb/sth that is considered to be holy or very important","cn":"敬重；崇敬；敬仰"}]}},"veterans":{"oxford":{"phon":"ˈvetərən","pos":"noun","senses":[{"en":"a person who has a lot of experience in a particular area or activity","cn":"经验丰富的人；老手"},{"en":"a person who has been a soldier, sailor, etc. in a war","cn":"退伍军人；老兵；老战士；老水兵"}]}},"ventured":{"oxford":{"phon":"ˈventʃə(r)","pos":"noun","senses":[{"en":"a business project or activity, especially one that involves taking risks （","cn":"尤指有风险的）企业，商业，投机活动，经营项目"},{"en":"to go somewhere even though you know that it might be dangerous or unpleasant","cn":"敢于去（危险或令人不快的地方）"}]}},"vehicles":{"oxford":{"phon":"ˈviːəkl","pos":"noun","senses":[{"en":"( rather formal ) a thing that is used for transporting people or goods from one place to another, such as a car or lorry/truck","cn":"交通工具；车辆"},{"en":"something that can be used to express your ideas or feelings or as a way of achieving sth （","cn":"赖以表达思想、感情或达到目的的）手段，工具"}]}},"versions":{"oxford":{"phon":"ˈvɜːʃn","pos":"noun","senses":[{"en":"a form of sth that is slightly different from an earlier form or from other forms of the same thing","cn":"变体；变种；型式"},{"en":"a description of an event from the position of a particular person or group of people （","cn":"从不同角度的）说法，描述"}]}},"verbs":{"oxford":{"phon":"vɜːb","pos":"noun","senses":[{"en":"a word or group of words that expresses an action (such as eat ), an event (such as happen ) or a state (such as exist )","cn":"动词"}]}},"venues":{"oxford":{"phon":"ˈvenjuː","pos":"noun","senses":[{"en":"a place where people meet for an organized event, for example a concert, sporting event or conference","cn":"活动场地（如音乐厅、体育比赛场馆、会场）"}]}},"vendors":{"oxford":{"phon":"ˈvendə(r)","pos":"noun","senses":[{"en":"a person who sells things, for example food or newspapers, usually outside on the street","cn":"小贩；摊贩"},{"en":"( formal ) a company that sells a particular product （","cn":"某种产品的）销售公司"}]}},"vegetate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"过单调无聊的生活;无所事事地生活","en":"If someone vegetates, they spend their time doing boring or worthless things.","ex":{"en":"He spends all his free time at home vegetating in front of the TV.","cn":"他一有空闲时间就窝在家里看电视。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to live without doing much physical or mental activity and to feel bored as a result","cn":"无所事事地生活﹐过枯燥呆板的生活"}]},"vocab":{"pos":"v","senses":[{"en":"When plants vegetate, they spread. When people vegetate, they relax. After a long day, if you want to vegetate or exert no effort in your body or mind, try sitting in front of the TV for hours."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41vegetate.mp3","us":"media/ldoce/hwd/ame/3/vegetate.mp3"},"examples":[{"en":"I was determined when I retired that I wasn’t just going to vegetate.","cn":"我退休时便下定决心绝不让生活过得单调无聊。"}],"oxford":{"phon":"ˈvedʒəteɪt","pos":"verb","senses":[{"en":"to spend time doing very little and feeling bored","cn":"过无聊生活；无所用心"}]}},"veer":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（突然）转向,改变方向","en":"If something veers in a certain direction, it suddenly moves in that direction.","ex":{"en":"The plane veered off the runway and careered through the perimeter fence","cn":"飞机突然偏离跑道，高速冲过了周围的护栏。"}},{"pos":"VERB 动词","cn":"改变立场（或态度）","en":"If someone or something veers in a certain direction, they change their position or direction in a particular situation.","ex":{"en":"He is unlikely to veer from his boss's strongly held views","cn":"他不可能背离他老板的强硬立场。"}},{"pos":"VERB 动词","cn":"（风）改变方向","en":"When the wind veers it changes direction.","ex":{"en":"The wind had veered from the west to north-by-west","cn":"风向已经改变，从西风转为西北风。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change your direction when you are walking or driving","cn":""},{"en":"to turn while you are moving so that you start going in a different direction","cn":""},{"en":"if a vehicle, ship, or aircraft changes course , it changes the direction in which it is travelling","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To veer is to make a sudden turn, like when a driver veers off the pavement, or a pleasant conversation veers off in a troubling direction."}]},"collocations":{"phrases":["ADV. sharply, violently, wildly The ship veered round wildly in the rough sea. | (to the) left, (to the) right | away, round The plane veere","PREP. between (figurative) He veered between calm acceptance and hysterical accusations. | from (figurative) The play veers from loopy comed"]},"media":{"uk":"media/ldoce/hwd/bre/f/veer0205.mp3","us":"media/ldoce/hwd/ame/b/veer.mp3"},"examples":[{"en":"His emotions veered between fear and anger.","cn":"他的情绪变化不定，一会儿恐惧一会儿生气。"},{"en":"The bus veered onto the wrong side of the road.","cn":"公共汽车突然驶入了逆行道。"}],"oxford":{"phon":"vɪə(r)","pos":"verb","senses":[{"en":"to change direction suddenly","cn":"突然变向；猛然转向","g":"[intransitive]","ex":{"en":"The bus veered onto the wrong side of the road.","cn":"公共汽车突然驶入了逆行道。"}},{"en":"to change in the way it develops","cn":"偏离；改变；转变","g":"[intransitive]","ex":{"en":"The debate veered away from the main topic of discussion.","cn":"争论脱离了讨论的主题。"}},{"en":"to change direction","cn":"改变方向","g":"[intransitive]","lab":"specialist","ex":{"en":"The wind veered to the west.","cn":"风向转西。"}}]}},"ventilator":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"人工呼吸器","en":"A ventilator is a machine that helps people breathe when they cannot breathe naturally, for example because they are very ill or have been seriously injured."},{"pos":"N-COUNT 可数名词","cn":"通风设备","en":"A ventilator is a device that lets fresh air into a room or building and lets old or dirty air out."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment that puts fresh air into a room, building etc","cn":"通风装置﹔排气风扇﹐送风机"},{"en":"a piece of equipment that pumps air into and out of someone’s lungs","cn":"人工呼吸机"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ventilator0205.mp3","us":"media/ldoce/hwd/ame/4/ventilator.mp3"},"examples":[{"en":"He was put on a ventilator.","cn":"给他戴上了呼吸器。"},{"en":"He was put on a ventilator but died two hours later.","cn":"他上了呼吸机﹐不过两小时后还是死亡了。"}],"oxford":{"phon":"ˈventɪleɪtə(r)","pos":"noun","senses":[{"en":"a device or an opening for letting fresh air come into a room, etc.","cn":"通风设备；通风口"},{"en":"a piece of medical equipment with a pump that helps somebody to breathe by sending air in and out of their lungs","cn":"通气机；呼吸器","ex":{"en":"He was put on a ventilator.","cn":"给他戴上了呼吸器。"}}]}},"vermouth":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"味美思酒;苦艾酒","en":"Vermouth is a strong alcoholic drink made from red or white wine flavoured with herbs."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an alcoholic drink made from wine with herbs and spices","cn":"味美思酒﹐苦艾酒"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41vermouth.mp3","us":"media/ldoce/hwd/ame/4/vermouth.mp3"},"examples":[{"en":"dry vermouth","cn":"干苦艾酒"}],"oxford":{"phon":"vɜːˈmuːθ","pos":"noun","senses":[{"en":"a strong wine, made with herbs and spices to add taste, often mixed with other drinks as a cocktail","cn":"味美思酒（以多种香草制成，常用以调配鸡尾酒）"}]}},"veracity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"真实;诚实","en":"Veracity is the quality of being true or the habit of telling the truth.","ex":{"en":"We have total confidence in the veracity of our research","cn":"我们对我们调查的真实性有十足的把握。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the fact of being true or correct","cn":"真实(性)﹔正确(性)"}]},"vocab":{"pos":"n","senses":[{"en":"Veracity sounds like some kind of disease you don't want to catch, but in fact, it means truthfulness. If you question the veracity of a statement or story, you wonder whether it is truthful or accurate."}]},"media":{"uk":"media/ldoce/hwd/bre/5/veracity0205.mp3","us":"media/ldoce/hwd/ame/e/veracity.mp3"},"examples":[{"en":"They questioned the veracity of her story.","cn":"他们质疑她所述事情的真实性。"},{"en":"Has anyone checked the veracity of these allegations?","cn":"有人核实过这些说法的真实性吗？"}],"oxford":{"phon":"vəˈræsəti","pos":"noun","senses":[{"en":"the quality of being true; the habit of telling the truth","cn":"真实；真实性；诚实","ex":{"en":"They questioned the veracity of her story.","cn":"他们质疑她所述事情的真实性。"}}]}},"veritable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"真正的，十足的，不折不扣的（用于强调大小、数量或性质等）","en":"You can use veritable to emphasize the size, amount, or nature of something.","ex":{"en":"...a veritable feast of pre-match entertainment.","cn":"尽情的赛前娱乐享受"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a word used to emphasize a description of someone or something","cn":"十足的﹐名副其实的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"When something is veritable it is true, or at least feels that way. \"The trees and lights turned the campus into a veritable wonderland\" means that the campus seemed to be transformed into a true wonderland (if there is such a thing)."}]},"media":{"uk":"media/ldoce/hwd/bre/b/veritable0205.mp3","us":"media/ldoce/hwd/ame/e/veritable.mp3"},"examples":[{"en":"The meal that followed was a veritable banquet.","cn":"随后摆上的饭菜俨然是一桌宴席。"},{"en":"The area is a veritable paradise for those who love walking and swimming.","cn":"这个地区对于喜欢散步和游泳的人来说简直就是天堂。"}],"oxford":{"phon":"ˈverɪtəbl","pos":"adjective","senses":[{"en":"a word used to emphasize that somebody/something can be compared to somebody/something else that is more exciting, more impressive, etc.","cn":"十足的；名副其实的；不折不扣的","ex":{"en":"The meal that followed was a veritable banquet.","cn":"随后摆上的饭菜俨然是一桌宴席。"}}]}},"vertigo":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（从高处俯视产生的）眩晕，头晕;恐高症","en":"If you get vertigo when you look down from a high place, you feel unsteady and sick.","ex":{"en":"If you have vertigo it seems as if the whole room is spinning round you","cn":"如果你头晕，就会觉得整个房间都旋转起来。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to feel frightened when you are in high places","cn":""},{"en":"a feeling that things are moving and that you are going to fall, that you get especially when you are on or in a high place","cn":""},{"en":"a feeling of sickness and dizziness caused by looking down from a high place 〔","cn":"因从高处俯视而产生的〕眩晕﹐头晕"}]},"vocab":{"pos":"n","senses":[{"en":"If you're standing still but the room is inexplicably spinning, you might want to let someone know you're suffering from vertigo — the sensation of dizziness or whirling."}]},"media":{"uk":"media/ldoce/hwd/bre/3/vertigo0205.mp3","us":"media/ldoce/hwd/ame/5/vertigo.mp3"},"oxford":{"phon":"ˈvɜːtɪɡəʊ","pos":"noun","senses":[{"en":"the feeling of dizziness and fear, and of losing your balance, that is caused in some people when they look down from a very high place","cn":"（从高处俯视时感到的）眩晕，头晕目眩"}]}},"verdant":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"草木覆盖的;长满绿色植物的","en":"If you describe a place as verdant, you mean that it is covered with green grass, trees, and plants.","ex":{"en":"...a small verdant garden with a view out over Paris.","cn":"能够俯瞰巴黎的郁郁葱葱的小花园"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"verdant land is thickly covered with fresh green plants 〔","cn":"土地〕长满青翠草木的"}]},"vocab":{"pos":"adj","senses":[{"en":"When something is green with plant life it's verdant, a word often used to idealize the countryside with its verdant pastures or verdant hills."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41verdant.mp3","us":"media/ldoce/hwd/ame/e/verdant.mp3"},"examples":[{"en":"verdant fields","cn":"葱茏的田野"}],"oxford":{"phon":"ˈvɜːdnt","pos":"adjective","senses":[{"en":"fresh and green","cn":"嫩绿的；碧绿的；青翠的"}]}},"vellum":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"羊皮纸;犊皮纸;上等纸","en":"Vellum is strong paper of good quality for writing on."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a material used for covering books or writing on, made from the skin of young cows, sheep, or goats","cn":"羊皮纸﹐犊皮纸〔用作书皮或用于书写〕"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41vellum.mp3","us":"media/ldoce/hwd/ame/4/vellum.mp3"},"examples":[{"en":"medieval maps inscribed on vellum","cn":"绘于羊皮纸上的中世纪地图"}],"oxford":{"phon":"ˈveləm","pos":"noun","senses":[{"en":"material made from the skin of a sheep, goat or calf, used for making book covers and, in the past, for writing on","cn":"（书封或旧时书写用的）羊皮纸，犊皮纸"},{"en":"smooth cream-coloured paper used for writing on","cn":"仿羊皮纸；仿犊皮纸"}]}},"velveteen":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"平绒;棉绒","en":"Velveteen is a soft fabric which looks and feels like velvet and is sometimes used as a cheaper alternative to velvet.","ex":{"en":"...a black velveteen coat.","cn":"黑色平绒大衣"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of cloth that is similar to velvet but cheaper","cn":"平绒﹐棉绒"}]},"vocab":{"pos":"n","senses":[{"en":"Velveteen is as soft as velvet, but it's not quite as fancy. Your favorite childhood stuffed animal might be made out of velveteen ."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41velveteen.mp3","us":"media/ldoce/hwd/ame/d/velveteen.mp3"},"oxford":{"phon":"ˈvelvətiːn","pos":"noun","senses":[{"en":"a type of cotton cloth that looks like velvet but is less expensive","cn":"棉绒；平绒；纬绒"}]}},"verity":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"真理;事实","en":"The verities of something are all the things that are believed to be true about it.","ex":{"en":"...some verities of human nature.","cn":"人性中一些真实的东西"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an important principle or fact that is always true","cn":"重要的真理[准则﹐事实]"}]},"vocab":{"pos":"n","senses":[{"en":"If your friend tells you she saw a UFO yesterday afternoon, you might be inclined to question the verity , or truthfulness, of her statement. Everyone knows UFOs are only visible at night."}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41verity.mp3","us":"media/ldoce/hwd/ame/8/verity.mp3"},"examples":[{"en":"the eternal verities of life","cn":"生命永恒的真理"}],"oxford":{"phon":"ˈverəti","pos":"noun","senses":[{"en":"a belief or principle about life that is accepted as true","cn":"（关于生命的）信念，准则，真理","g":"[usually plural]","lab":"formal","ex":{"en":"the eternal verities of life","cn":"生命永恒的真理"}},{"en":"truth","cn":"真理；客观事实","g":"[uncountable]","lab":"old use"}]}},"vestigial":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"残存的;残余的;遗留的","en":"Vestigial is used to describe the small amounts of something that still remain of a larger or more important thing.","ex":{"en":"Vestigial remains of these plays are now seen in the Christmas pantomime.","cn":"在圣诞节演出的哑剧中还能看到这些戏剧残留下来的痕迹。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a vestigial part of the body has never developed completely or has almost disappeared 〔","cn":"器官等〕退化的"},{"en":"remaining as a sign that something existed after most of it has gone","cn":"残余的﹐残留的﹐遗迹的"}]},"vocab":{"pos":"adj","senses":[{"en":"Vestigial describes an organ or body part that continues to exist without retaining its original function, such as our appendix."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41vestigial.mp3","us":"media/ldoce/hwd/ame/8/vestigial.mp3"},"examples":[{"en":"It is often possible to see the vestigial remains of rear limbs on some snakes.","cn":"在某些蛇身上常可看到退化后肢的痕迹。"},{"en":"vestigial traces of an earlier culture","cn":"早期文化的遗迹"}],"oxford":{"phon":"veˈstɪdʒiəl","pos":"adjective","senses":[{"en":"that remain as the last small part of something that used to exist","cn":"残留的；残余的；退化的","ex":{"en":"vestigial traces of an earlier culture","cn":"早期文化的遗迹"}}]}},"venue":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（事件或活动的）发生地,举办地点;场地","en":"The venue for an event or activity is the place where it will happen.","ex":{"en":"Birmingham's International Convention Centre is the venue for a three-day arts festival","cn":"为期3天的艺术节在伯明翰的国际会议中心举办。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a point or area, especially one that you visit or use for a particular purpose","cn":""},{"en":"the exact place where someone or something is, in relation to other things","cn":""},{"en":"a particular place on a line or surface","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A venue is the place where an event or meeting is happening. If you're going to see the best band ever, you should get to the venue early to get a good seat."}]},"collocations":{"phrases":["ADJ. ideal, perfect, popular, prestigious, top Europe's top venue for indoor athletics | intimate With room for only 200 people, this is the","VERB + VENUE be, provide The Holiday Inn provided the venue for this year's conference. | hire | play | pack (out) The musical has been pack","PREP. at a/the ~ The meeting will be held at a venue in the south of the city. | in a/the ~ She has performed in venues around Europe. | ~ f","PHRASES a change of venue"]},"media":{"uk":"media/ldoce/hwd/bre/7/venue0205.mp3","us":"media/ldoce/hwd/ame/4/venue.mp3"},"examples":[{"en":"The band will be playing at 20 different venues on their UK tour.","cn":"这个乐队在英国巡回演出期间将在 20 个不同的地点演出。"},{"en":"Please note the change of venue for this event.","cn":"请注意：这次比赛易地进行。"}],"oxford":{"phon":"ˈvenjuː","pos":"noun","senses":[{"en":"a place where people meet for an organized event, for example a concert, sporting event or conference","cn":"活动场地（如音乐厅、体育比赛场馆、会场）","ex":{"en":"The band will be playing at 20 different venues on their UK tour.","cn":"这支乐队在英国巡回演出期间将在 20 个不同的地点演出。"}}]}},"vehicular":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"车辆的;交通工具的;交通的","en":"Vehicular is used to describe something which relates to vehicles and traffic.","ex":{"en":"...vehicular traffic","cn":"车辆交通"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to vehicles","cn":"车辆的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective vehicular when you're talking about something that has to do with a car or truck. Vehicular traffic is simply the number of motorized vehicles on a certain road at the same time."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41vehicular.mp3","us":"media/ldoce/hwd/ame/0/vehicular.mp3"},"examples":[{"en":"The road is closed to vehicular traffic.","cn":"此路禁止车辆通行。"},{"en":"vehicular access","cn":"车辆入口"}],"oxford":{"phon":"vəˈhɪkjələ(r)","pos":"adjective","senses":[{"en":"intended for vehicles or consisting of vehicles","cn":"供车辆等使用的；车辆的；运输工具的","ex":{"en":"vehicular access","cn":"车辆入口"}}]}},"vegetarianism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"素食主义","en":"If someone practises vegetarianism, they never eat meat or fish.","ex":{"en":"Vegetarianism is on the increase in Britain.","cn":"素食主义在英国越来越盛行。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the practice of not eating meat or fish","cn":"素食主义"}]},"media":{"uk":"media/ldoce/hwd/bre/4/vegetarianism0205.mp3","us":"media/ldoce/hwd/ame/6/vegetarianism.mp3"},"oxford":{"phon":"ˌvedʒəˈteəriənɪzəm","pos":"noun","senses":[{"en":"the practice of eating no meat or fish","cn":"素食主义","ex":{"en":"the ethics of vegetarianism","cn":"素食主义的伦理"}}]}},"veneer":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"虚饰;伪装;假象","en":"If you refer to the pleasant way that someone or something appears as a veneer, you are critical of them because you believe that their true, hidden nature is not good.","ex":{"en":"He was able to fool the world with his veneer of education","cn":"他打着受过良好教育的幌子到处欺瞒世人。"}},{"pos":"N-VAR 可变名词","cn":"饰面薄板;镶板","en":"Veneer is a thin layer of wood or plastic which is used to improve the appearance of something.","ex":{"en":"The wood was cut into large sheets of veneer","cn":"木料被锯成大块的薄板。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thin layer of wood or plastic that covers the surface of a piece of furniture made of cheaper material, to make it look better","cn":"饰面板﹐贴面板〔覆于家具表面的薄木板或塑料板〕"},{"en":"behaviour that hides someone’s real character or feelings 〔","cn":"掩饰真实性格或感情的〕彬彬有礼/世故等的伪装"}]},"vocab":{"pos":"n v","senses":[{"en":"You know how some furniture looks like solid oak or maple until it gets chipped and reveals itself to be nothing more than some cheap particle-board covered with a thin layer of fancy wood? That thin layer is called a veneer ."}]},"collocations":{"phrases":["ADJ. thin | false | civilized","VERB + VENEER acquire | strip (off), strip sb/sth of They hav e stripped the veneer of jingois m from the play, by showing war i n its true ","VENEER + VERB disguise sth, hide sth, mask sth He managed to acquire a thin veneer of knowledge to mask his real ignorance. | crack For the ","PREP. behind/below/beneath/under a/the ~ They're brutal peopl e behind their civilized veneer. | ~ of"]},"media":{"uk":"media/ldoce/hwd/bre/e/veneer0205.mp3","us":"media/ldoce/hwd/ame/4/veneer1.mp3"},"examples":[{"en":"Her veneer of politeness began to crack.","cn":"她那彬彬有礼的伪装开始露馅儿了。"},{"en":"A thin veneer of politeness hid Lady Bride’s growing anger.","cn":"布赖德夫人看上去不失礼数﹐内心的怒火却是愈燃愈烈。"}],"oxford":{"phon":"vəˈnɪə(r)","pos":"noun","senses":[{"en":"a thin layer of wood or plastic that is stuck to the surface of cheaper wood with glue, especially on a piece of furniture","cn":"饰面薄板，薄片镶饰（尤用于家具上）","g":"[countable, uncountable]","ex":{"en":"pine, with a walnut veneer","cn":"松木，胡桃木贴面"}},{"en":"an outer appearance of a particular quality that hides the true nature of somebody/something","cn":"虚假的外表；虚饰","g":"[singular]","lab":"formal","ex":{"en":"Her veneer of politeness began to crack.","cn":"她那彬彬有礼的伪装开始露馅儿了。"}},{"en":"to cover the surface of something with a veneer of wood, etc.","cn":"（用薄片镶饰等）饰面，覆盖","ex":{"en":"The bed was veneered with cherrywood.","cn":"床的表层是樱桃木镶板。"},"pos":"verb"}]}},"ventricle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"心室","en":"A ventricle is a part of the heart that pumps blood to the arteries."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the two spaces in the bottom of your heart through which blood pumps out to your body","cn":"心室"}]},"vocab":{"pos":"n","senses":[{"en":"A ventricle is one of the chambers of the heart. It pumps blood to your arteries."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41ventricle.mp3","us":"media/ldoce/hwd/ame/3/ventricle.mp3"},"oxford":{"phon":"ˈventrɪkl","pos":"noun","senses":[{"en":"either of the two lower spaces in the heart that pump blood to the lungs or around the body","cn":"心室"},{"en":"any hollow space in the body, especially one of four main hollow spaces in the brain","cn":"（体内的）室，腔；（尤指）脑室"}]}},"vector":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"矢量;向量","en":"A vector is a variable quantity, such as force, that has size and direction."},{"pos":"N-COUNT 可数名词","cn":"（传播疾病的）媒介昆虫，带菌生物","en":"A vector is an insect or other organism that causes a disease by carrying a germ or parasite from one person or animal to another."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a quantity such as force that has a direction as well as size","cn":"矢量﹐向量"},{"en":"an insect or animal that passes disease from one person to another 〔","cn":"传播疾病的〕媒介﹐载体"},{"en":"in biology, an animal or human cell that is used to carry DNA from one cell to another to produce a clone","cn":"克隆载体"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"One definition of a vector is that of a carrier — it might be an insect like a mosquito that carries and transmits a bacterium or virus, or it might be some agent that carries genetically engineered DNA into a cell."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41vector.mp3","us":"media/ldoce/hwd/ame/6/vector.mp3"},"examples":[{"en":"Acceleration and velocity are both vectors.","cn":"加速度和速度都是矢量。"},{"en":"Mosquitoes are feared as vectors of malaria.","cn":"蚊子作为疟疾的传播媒介为人所惧。"}],"oxford":{"phon":"ˈvektə(r)","pos":"noun","senses":[{"en":"a quantity that has both size and direction","cn":"向量；矢量","lab":"mathematics","ex":{"en":"Acceleration and velocity are both vectors.","cn":"加速度和速度都是矢量。"}},{"en":"an insect, etc. that carries a particular disease from one living thing to another","cn":"（传染疾病的）介体，载体","lab":"biology","ex":{"en":"Mosquitoes are the vectors in malaria.","cn":"蚊子是传播疟疾的媒介。"}},{"en":"a course taken by an aircraft","cn":"（航空器的）航线","lab":"specialist"}]}},"vexation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"恼火;困惑;烦恼","en":"Vexation is a feeling of being annoyed, puzzled, and frustrated.","ex":{"en":"He kicked the broken machine in vexation.","cn":"他气得踢了那台坏机器一脚。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you feel worried or annoyed by something","cn":"烦恼﹐苦恼﹔恼火"},{"en":"something that worries or annoys you","cn":"令人烦恼[恼火]的事"}]},"vocab":{"pos":"n","senses":[{"en":"Vexation is both something that causes annoyance and the state of mind that results from being annoyed. The test-taker next to you tapping her pencil is a vexation . You breaking her pencil in half makes her feel vexation ."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41vexation.mp3","us":"media/ldoce/hwd/ame/1/vexation.mp3"},"examples":[{"en":"Erika stamped her foot in vexation.","cn":"埃丽卡恼火地跺了跺脚。"}],"oxford":{"phon":"vekˈseɪʃn","pos":"noun","senses":[{"en":"the state of feeling upset or annoyed","cn":"烦恼；恼火；伤脑筋；心烦意乱","g":"[uncountable]","ex":{"en":"She sat down and cried in vexation.","cn":"她坐下来，伤心地哭了。"}},{"en":"a thing that upsets or annoys you","cn":"令人心烦（或恼火）的事","g":"[countable]"}]}},"vex":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使恼火;使困惑;使伤脑筋","en":"If someone or something vexes you, they make you feel annoyed, puzzled, and frustrated.","ex":{"en":"It vexed me to think of others gossiping behind my back","cn":"一想到别人在背后说我闲话，我就很恼火。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone feel annoyed or worried","cn":"使恼怒﹔使烦恼"}]},"vocab":{"pos":"v","senses":[{"en":"If something vexes you, it brings you trouble or difficulty. In other words, it annoys, worries, distresses, irritates, bothers, or puzzles you."}]},"media":{"uk":"media/ldoce/hwd/bre/3/vex0205.mp3","us":"media/ldoce/hwd/ame/7/vex.mp3"},"examples":[{"en":"a vexing problem","cn":"令人烦恼的问题"}],"oxford":{"phon":"veks","pos":"verb","senses":[{"en":"to annoy or worry somebody","cn":"使恼火；使烦恼；使忧虑","ex":{"en":"The memory of their conversation still vexed him.","cn":"他们谈话的记忆仍然使他烦恼。"}}]}},"vexed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人烦恼的;伤脑筋的;棘手的","en":"A vexed problem or question is very difficult and causes people a lot of trouble.","ex":{"en":"Ministers have begun work on the vexed issue of economic union","cn":"部长们开始着手处理经济联盟这个棘手的问题。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a complicated problem that has caused a lot of discussion and argument and is difficult to solve","cn":"引起争论[棘手]的问题"},{"en":"annoyed or worried","cn":"恼火的﹔焦虑的"}]},"vocab":{"pos":"adj","senses":[{"en":"Vexed means \"difficult and much debated.\" If your family is having trouble coming to an agreement about where to go on vacation next summer, your holiday trip has become a vexed issue."}]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdevexed.mp3","us":"media/ldoce/hwd/ame/7/laadvexed.mp3"},"examples":[{"en":"The conference spent days discussing the vexed question of border controls.","cn":"会议花了几天的时间讨论边境管制这个难题。"},{"en":"the vexed question of sexism","cn":"棘手的性别歧视问题"}],"oxford":{"phon":"vekst","pos":"adjective","senses":[{"en":"a problem that is difficult to deal with","cn":"（问题等）棘手的，伤脑筋的","ex":{"en":"The conference spent days discussing the vexed question of border controls.","cn":"会议花了几天的时间讨论边境管制这个难题。"}},{"en":"upset or annoyed","cn":"（人）恼火，烦恼，伤脑筋","lab":"old-fashioned","ex":{"en":"Are you vexed with me?","cn":"你生我的气吗？"}}]}},"verdigris":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"铜绿;铜锈","en":"Verdigris is a greenish-blue substance that forms on the metals copper, brass, and bronze after they have been left in wet or damp conditions."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a greenish-blue substance that sometimes appears on copper or brass 〔","cn":"铜器上的〕铜绿"}]},"vocab":{"pos":"n v","senses":[{"en":"Verdigris is the blue-green tarnish on certain metals after they are left outside for a long period of time. A lot of churches have rooftops coated with verdigris , and many capitol buildings have verdigris on their domes."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41verdigris.mp3","us":"media/ldoce/hwd/ame/5/verdigris.mp3"},"oxford":{"phon":"ˈvɜːdɪɡriː","pos":"noun","senses":[{"en":"the green substance that forms, for example on roofs, when copper reacts with the air","cn":"铜绿，碱式碳酸铜（铜遇空气发生反应形成）"}]}},"verily":{"collins":{"senses":[{"pos":"ADV 副词","cn":"真实地;确实","en":"Verily is an old-fashioned or religious word meaning 'truly'. It is used to emphasize a statement or opinion.","ex":{"en":"Verily I say unto you, that one of you shall betray me.","cn":"我实在告诉你们，你们中间有一个人要卖我了。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"a word used to emphasize a statement","cn":"真实地﹐确实"}]},"vocab":{"pos":"adv","senses":[{"en":"Use the adverb verily when you need an old-fashioned way to say \"certainly.\" For example, you might say, \"I verily believe that's the ugliest sweater I've ever seen.\""}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41verily.mp3","us":"media/ldoce/hwd/ame/c/verily.mp3"},"oxford":{"phon":"ˈverɪli","pos":"adverb","senses":[{"en":"really; truly","cn":"真正地；真实地"}]}},"veterinarian":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"兽医","en":"A veterinarian is a person who is qualified to treat sick or injured animals."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is trained to give medical care and treatment to sick animals","cn":"兽医"}]},"vocab":{"pos":"n","senses":[{"en":"A veterinarian is a doctor for animals. When it’s time for your dog to get his shots, you take him to the veterinarian ."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41veterinarian.mp3","us":"media/ldoce/hwd/ame/4/veterinarian.mp3"},"oxford":{"phon":"ˌvetərɪˈneəriən","pos":"noun","senses":[{"en":"a person who has been trained in the science of animal medicine, whose job is to treat animals who are sick or injured","cn":"兽医","ex":{"en":"Consult your veterinarian if your cat is still not eating.","cn":"如果你家的猫仍然不进食，请咨询兽医。"}}]}},"vertebrate":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"脊椎动物","en":"A vertebrate is a creature which has a spine. Mammals, birds, reptiles, and fish are vertebrates.","ex":{"en":"Both groups share two attributes normally associated with vertebrates.","cn":"两组都具有通常脊椎动物才具备的两个特征。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a living thing such as a dog, cow, or tiger, but not an insect, fish, or bird","cn":""},{"en":"an animal – used especially when describing a particular animal’s characteristics or when referring to animals generally","cn":""},{"en":"an animal, especially a large or dangerous one","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"A vertebrate is an animal that has a backbone and a skeleton. Vertebrate animals include humans."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41vertebrate.mp3","us":"media/ldoce/hwd/ame/b/vertebrate.mp3"},"oxford":{"phon":"ˈvɜːtɪbrət","pos":"adjective","senses":[{"en":"having a backbone","cn":"有脊椎的"},{"en":"any animal with a backbone, including all mammals, birds, fish, reptiles and amphibians","cn":"脊椎动物（包括所有哺乳动物、鸟类、鱼类、爬行动物和两栖动物）","pos":"noun"}]}},"verifiable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可证实的;可核实的","en":"Something that is verifiable can be proved to be true or genuine.","ex":{"en":"This is not a romantic notion but verifiable fact","cn":"这不是一个不切实际的念头，而是一个可以证明的事实。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do something in order to find out whether something is really true or correct","cn":""},{"en":"to make sure that something, especially something that someone else has told you, is actually true","cn":""},{"en":"to check that a situation is really the way you want or expect it to be","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/verify0205.mp3","us":"media/ldoce/hwd/ame/a/verify.mp3"},"examples":[{"en":"a verifiable fact","cn":"可核实的事实"},{"en":"A computer program verifies that the system is working.","cn":""}],"oxford":{"phon":"ˈverɪfaɪəbl","pos":"adjective","senses":[{"en":"that can be checked to show whether it is true or accurate","cn":"可核实的；能证实的；可查证的","ex":{"en":"a verifiable fact/claim","cn":"可验证的事实/主张"}}]}},"vegan":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"严格素食的;不吃肉的","en":"Someone who is vegan never eats meat or any animal products such as milk, butter, or cheese.","ex":{"en":"The menu changes weekly and usually includes a vegan option","cn":"菜单每周都有变化，通常包含可供严格的素食者选择的菜肴。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who does not eat any animal products at all, such as meat, fish, eggs, cheese, or milk 〔","cn":"不吃动物制品的〕纯素食者﹐严格的素食主义者"}]},"vocab":{"pos":"n","senses":[{"en":"If you’re a vegan , you’re a strict vegetarian, and you don’t eat anything from an animal — not even eggs or dairy. If you’re a really strict vegan , you may not even eat honey or wear leather."}]},"media":{"uk":"media/ldoce/hwd/bre/6/vegan0205.mp3","us":"media/ldoce/hwd/ame/f/ld45vegan.mp3"},"oxford":{"phon":"ˈviːɡən","pos":"noun","senses":[{"en":"a person who does not eat any animal products such as meat, milk or eggs or use animal products such as leather or wool","cn":"严格素食主义者（不吃肉、奶、蛋等，或不用皮、毛等动物产品）","ex":{"en":"He’s a strict vegan.","cn":"他是一位严格的素食主义者。"}},{"en":"using or containing no animal products","cn":"严格素食的；不含动物产品的","ex":{"en":"a vegan diet","cn":"纯素饮食"},"pos":"adjective"}]}},"vegetative":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"植物人状态的;植物人的","en":"If someone is in a vegetative state, they are unable to move, think, or speak, and their condition is not likely to improve.","ex":{"en":"She was in what was described as a vegetative state.","cn":"她处于一种被称为植物人的状态。"}},{"pos":"ADJ 形容词","cn":"植物的;植物生长的","en":"Vegetative growth or development is the growth or development of plants.","ex":{"en":"The harshness of the climate makes vegetative growth extremely slow.","cn":"恶劣的气候使植物生长特别缓慢。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to plants, and particularly to the way they grow or make new plants 〔","cn":"尤指生长或繁殖方式〕植物的﹐植物性的"},{"en":"a condition in which someone cannot think or move because their brain has been damaged","cn":"植物人状态"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective vegetative to describe a physically or mentally inactive person. If you lie around on the couch all day flipping TV channels, your sister may accuse you of being in a vegetative state."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41vegetative.mp3","us":"media/ldoce/hwd/ame/a/laadvegetative.mp3"},"oxford":{"phon":"ˈvedʒɪtətɪv","pos":"adjective","senses":[{"en":"relating to plant life","cn":"植物的；植物性的"},{"en":"alive but showing no sign of brain activity","cn":"植物人状态的","lab":"medical"}]}},"veldt":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"（南非的）稀树草原","en":"The veldt is a high area of flat grassy land with very few trees in southern Africa.","ex":{"en":"...a gang of hyenas, stalking about the veldt.","cn":"一群在草原上游弋的土狼"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"high flat land in South Africa that is covered in grass and has few trees 〔","cn":"南非高原上的〕草原"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41veldt.mp3","us":"media/ldoce/hwd/ame/d/laadveldt.mp3"}},"vertebra":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"脊椎;椎骨;脊柱","en":"Vertebrae are the small circular bones that form the spine of a human being or animal."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the small hollow bones down the centre of your back","cn":"椎骨"}]},"vocab":{"pos":"n","senses":[{"en":"A vertebra is one of the little bones in your spinal column; there are vertebrae up and down your back."}]},"media":{"uk":"media/ldoce/hwd/bre/2/vertebra0205.mp3","us":"media/ldoce/hwd/ame/d/vertebra.mp3"},"oxford":{"phon":"ˈvɜːtɪbrə","pos":"noun","senses":[{"en":"any of the small bones that are connected together to form the backbone","cn":"椎骨；脊椎"}]}},"velocity":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"速度;速率","en":"Velocity is the speed at which something moves in a particular direction.","ex":{"en":"...the velocity of light.","cn":"光速"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"how fast things happen, change, or develop","cn":""},{"en":"how fast someone walks or runs, or how fast they work or do things","cn":""},{"en":"the speed at which something moves in a particular direction - use this especially in technical contexts","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If your rocket is traveling at maximum velocity , it means it can't go any faster. Velocity is quickness of motion or action."}]},"collocations":{"phrases":["ADJ. enormous, high | low | constant, uniform | average, mean | maximum","VERB + VELOCITY achieve, attain, reach Eventually, the star attained the velocity of light. | move with to move with a uniform velocity | in","VELOCITY + VERB increase, rise | decrease, fall","PREP. at a/the ~ Light travels at a constant velocity."]},"media":{"uk":"media/ldoce/hwd/bre/7/velocity0205.mp3","us":"media/ldoce/hwd/ame/d/velocity.mp3"},"examples":[{"en":"Jaguars can move with an astonishing velocity.","cn":"美洲豹跑起来速度惊人。"},{"en":"to gain/lose velocity","cn":"加/减速"}],"oxford":{"phon":"vəˈlɒsəti","pos":"noun","senses":[{"en":"the speed of something in a particular direction","cn":"（沿某一方向的）速度","lab":"specialist","ex":{"en":"the velocity of light","cn":"光速"}},{"en":"high speed","cn":"高速；快速","lab":"formal","ex":{"en":"Jaguars can move with an astonishing velocity.","cn":"美洲豹跑起来速度惊人。"}}]}},"velour":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"丝绒;棉绒","en":"Velour is a silk or cotton fabric similar to velvet.","ex":{"en":"...black velour hats.","cn":"黑丝绒帽子"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of heavy cloth that is similar to velvet but cheaper","cn":"棉绒﹔丝绒"}]},"media":{"uk":"media/ldoce/hwd/bre/e/velour0205.mp3","us":"media/ldoce/hwd/ame/7/laadvelour.mp3"},"examples":[{"en":"gold velour curtains","cn":"金色丝绒窗帘"}],"oxford":{"phon":"vəˈlʊə(r)","pos":"noun","senses":[{"en":"a type of silk or cotton cloth with a thick, soft surface like velvet","cn":"丝绒；拉绒织物；维罗绒"}]}},"venom":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"怨恨;痛恨；恶意","en":"You can use venom to refer to someone's feelings of great bitterness and anger towards someone.","ex":{"en":"He reserved particular venom for critics of his foreign policy","cn":"他对那些批评他外交政策的人格外心怀怨恨。"}},{"pos":"N-MASS 物质名词","cn":"（毒蛇、蜘蛛等生物的）毒液，毒汁","en":"The venom of a creature such as a snake or spider is the poison that it puts into your body when it bites or stings you.","ex":{"en":"...snake handlers who grow immune to snake venom.","cn":"对蛇毒产生免疫力的玩蛇人"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"great anger or hatred","cn":"恶毒﹐恶意﹔怨恨﹐憎恨"},{"en":"a liquid poison that some snakes, insects etc produce when they bite or sting you 〔","cn":"蛇﹑昆虫等分泌的〕毒液"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"We’re pretty sure you wouldn’t drink a mysterious substance labeled “poisonous snake venom ,” even if you didn’t know the meaning of venom . However, just to be clear, venom means \"poison.\" Stay away from it."}]},"collocations":{"phrases":["ADJ. deadly | snake, spider, etc.","VENOM + VERB inject, spit The snake injects the venom immediately after biting its prey.","VENOM + NOUN gland 2 extreme anger or hatred","ADJ. pure, real, undisguised a look of pure venom","VERB + VENOM spit She surveyed him coldly with eyes that spat venom.","PREP. with ~ She said it quickly and with venom."]},"media":{"uk":"media/ldoce/hwd/bre/a/venom0205.mp3","us":"media/ldoce/hwd/ame/4/venom.mp3"},"examples":[{"en":"a look of pure venom","cn":"恶狠狠的样子"},{"en":"There was real venom in her voice.","cn":"她的声音非常凶狠。"}],"oxford":{"phon":"ˈvenəm","pos":"noun","senses":[{"en":"the poisonous liquid that some snakes, spiders, etc. produce when they bite or sting you","cn":"（毒蛇、蜘蛛等分泌的）毒液","ex":{"en":"The snake injects the venom immediately after biting its prey.","cn":"毒蛇咬住猎物之后马上注入毒液。"}},{"en":"a strong, bitter feeling; feelings of hate and a desire to hurt somebody","cn":"恶毒；怨恨；恶意；歹心","lab":"formal","ex":{"en":"His voice was full of venom.","cn":"他的声音里充满了恶意。"}}]}},"veterinary":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"兽医的","en":"Veterinary is used to describe the work of a person whose job is to treat sick or injured animals, or to describe the medical treatment of animals.","ex":{"en":"It was decided that our veterinary screening of horses at events should be continued.","cn":"已经决定继续对参赛马匹进行疾病筛查。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to the medical care and treatment of sick animals","cn":"兽医的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdeveterinary.mp3","us":"media/ldoce/hwd/ame/7/veterinary.mp3"},"examples":[{"en":"veterinary medicine/science","cn":"兽医学"},{"en":"veterinary medicine","cn":"兽医学"}],"oxford":{"phon":"ˈvetnri","pos":"adjective","senses":[{"en":"connected with caring for the health of animals","cn":"兽医的","ex":{"en":"veterinary medicine/science","cn":"兽医学"}}]}},"venerate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"尊重;敬仰;崇敬","en":"If you venerate someone or something, you value them or feel great respect for them.","ex":{"en":"My father venerated General Eisenhower.","cn":"我父亲十分敬仰艾森豪威尔将军。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to honour or respect someone or something because they are old, holy, or connected with the past","cn":"尊敬﹐崇拜﹐敬重"}]},"vocab":{"pos":"v","senses":[{"en":"To venerate is to worship, adore, be in awe of. You probably don't venerate your teacher or boss; however, you may act like you do!"}]},"media":{"uk":"media/ldoce/hwd/bre/f/venerate0205.mp3","us":"media/ldoce/hwd/ame/3/venerate.mp3"},"examples":[{"en":"The relics were objects of veneration.","cn":"这些圣人遗物是备受敬奉之物。"},{"en":"a symbol of Arab courage, to be venerated for generations","cn":"受到世代尊崇的阿拉伯人勇气的象征"}],"oxford":{"phon":"ˈvenəreɪt","pos":"verb","senses":[{"en":"to have and show a lot of respect for somebody/something, especially somebody/something that is considered to be holy or very important","cn":"敬重；崇敬；敬仰","ex":{"en":"The monk was subsequently venerated as a saint.","cn":"后来这位和尚被尊为圣人。"}}]}},"venous":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"静脉的","en":"Venous is used to describe something which is related to veins.","ex":{"en":"...venous blood.","cn":"静脉血"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to the vein s (= tubes that carry blood ) in your body","cn":"静脉的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41venous.mp3","us":"media/ldoce/hwd/ame/9/venous.mp3"},"examples":[{"en":"venous blood","cn":"静脉血"}],"oxford":{"phon":"ˈviːnəs","pos":"adjective","senses":[{"en":"of or contained in veins (= the tubes that carry liquids around the bodies of animals and plants)","cn":"静脉的；静脉中的；叶脉的","ex":{"en":"venous blood","cn":"静脉血"}}]}},"ventilation":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to let fresh air into a room, building etc","cn":""},{"en":"to pump air into and out of someone’s lungs, using a special machine","cn":""},{"en":"to express your opinions or feelings about something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Ventilation is when you let fresh air into a place, or air a room out."}]},"collocations":{"phrases":["ADJ. adequate, good Inspectors checked that there was adequate ventilation. | inadequate, poor | artificial, mechanical | natural | through ","VERB + VENTILATION give, provide Zips up the sides of the jacket give good ventilation.","VENTILATION + NOUN system | brick, duct, grille, hole, opening, pipe, shaft, slit, tube"]},"media":{"uk":"media/ldoce/hwd/bre/c/ventilate0205.mp3","us":"media/ldoce/hwd/ame/a/ventilate.mp3"},"examples":[{"en":"Make sure that there is adequate ventilation in the room before using the paint.","cn":"在使用油漆前确保室内通风充足。"},{"en":"a ventilation shaft","cn":"通风井"}],"oxford":{"phon":"ˌventɪˈleɪʃn","pos":"noun","senses":[{"en":"the fact of allowing fresh air to enter and move around a room, building, etc.","cn":"使（房间、建筑物等）通风；使通气","ex":{"en":"a ventilation shaft","cn":"通风井"}}]}},"verification":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do something in order to find out whether something is really true or correct","cn":""},{"en":"to make sure that something, especially something that someone else has told you, is actually true","cn":""},{"en":"to check that a situation is really the way you want or expect it to be","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Verification is an extra or final bit of proof that establishes something is true."}]},"collocations":{"phrases":["ADJ. empirical, scientific","VERIFICATION + NOUN procedures","PREP. subject to ~ The credit card is then accepted, subject to verification of the signature."]},"media":{"uk":"media/ldoce/hwd/bre/8/verify0205.mp3","us":"media/ldoce/hwd/ame/a/verify.mp3"},"examples":[{"en":"the verification of hypotheses","cn":"对假说的证实"},{"en":"A computer program verifies that the system is working.","cn":""}],"oxford":{"phon":"ˌverɪfɪˈkeɪʃn","pos":"noun","senses":[{"en":"the act of showing or checking that something is true or accurate","cn":"核实；查对；核准","ex":{"en":"the verification of hypotheses","cn":"对假说的验证"}}]}},"veal":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"小牛肉","en":"Veal is meat from a calf."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the meat of a calf (= a young cow )","cn":"小牛肉"}]},"media":{"uk":"media/ldoce/hwd/bre/c/veal0205.mp3","us":"media/ldoce/hwd/ame/b/veal.mp3"},"oxford":{"phon":"viːl","pos":"noun","senses":[{"en":"meat from a calf (= a young cow)","cn":"小牛肉；牛犊肉"}]}},"vestibule":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"门厅;前厅","en":"A vestibule is an enclosed area between the outside door of a building and the inside door."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a space inside the front door of a public building 〔","cn":"公共建筑物前门内的〕门厅﹐前厅"},{"en":"the space at each end of a railway carriage that connects it with the next carriage 〔","cn":"连接火车前后车厢的〕通廊﹐连廊"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A vestibule is a little area just inside the main door of a building, but before a second door. You often find vestibules in churches, because they help keep heat from escaping every time someone enters or exits."}]},"media":{"uk":"media/ldoce/hwd/bre/3/vestibule0205.mp3","us":"media/ldoce/hwd/ame/b/vestibule.mp3"},"oxford":{"phon":"ˈvestɪbjuːl","pos":"noun","senses":[{"en":"an entrance hall of a large building, for example where hats and coats can be left","cn":"前厅，门厅（如可放衣帽处）","lab":"formal","ex":{"en":"The flooring of the church vestibule is made of Italian marble.","cn":"教堂前厅的地板由意大利大理石制成。"}},{"en":"a space at the end of a coach on a train that connects it with the next coach","cn":"通过台（列车两个车厢间的连接处）","lab":"specialist"}]}},"verify":{"collins":{"senses":[{"pos":"VERB 动词","cn":"核实;查证;查清","en":"If you verify something, you check that it is true by careful examination or investigation.","ex":{"en":"I verified the source from which I had that information","cn":"我核实了我所获消息的来源。"}},{"pos":"VERB 动词","cn":"证实;证明","en":"If you verify something, you state or confirm that it is true.","ex":{"en":"The government has not verified any of those reports","cn":"政府还没有证实那些报告中的任何一个。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do something in order to find out whether something is really true or correct","cn":""},{"en":"to make sure that something, especially something that someone else has told you, is actually true","cn":""},{"en":"to check that a situation is really the way you want or expect it to be","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you verify something, you show that it's true. Do you have a photograph to verify your claim that there's a dinosaur in your backyard?"}]},"media":{"uk":"media/ldoce/hwd/bre/8/verify0205.mp3","us":"media/ldoce/hwd/ame/a/verify.mp3"},"examples":[{"en":"Her version of events was verified by neighbours.","cn":"她对这些事件的说法已得到邻居的证实。"},{"en":"Please verify that there is sufficient memory available before loading the program.","cn":"请在核实有足够的内存后再安装程序。"}],"oxford":{"phon":"ˈverɪfaɪ","pos":"verb","senses":[{"en":"to check that something is true or accurate","cn":"核实；查对；核准","ex":{"en":"We have no way of verifying his story.","cn":"我们无法核实他的说法。"}},{"en":"to show or say that something is true or accurate","cn":"证明；证实","ex":{"en":"Her version of events was verified by neighbours.","cn":"她对这些事件的说法已得到邻居的证实。"}}]}},"vetch":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"巢菜;野豌豆","en":"Vetch is a wild plant. Some types of vetch are sometimes grown as a crop."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a plant with small flowers, often used to feed farm animals","cn":"巢菜﹐野豌豆〔常用作饲料〕"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41vetch.mp3","us":"media/ldoce/hwd/ame/4/ld41vetch.mp3"},"oxford":{"phon":"vetʃ","pos":"noun","senses":[{"en":"a plant of the pea family. There are several types of vetch, one of which is used as food for farm animals.","cn":"巢菜，野豌豆（有一种可作饲料）"}]}},"vehement":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"激情的;激烈的;暴烈的","en":"If a person or their actions or comments are vehement, the person has very strong feelings or opinions and expresses them forcefully.","ex":{"en":"She suddenly became very vehement and agitated, jumping around and shouting","cn":"她突然变得激动狂躁，四处乱跳还大喊大叫。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"showing very strong feelings or opinions","cn":"感情强烈的﹔观点激烈的"},{"en":"vehement opposition/criticism/hostility etc Despite vehement opposition, the Act became law.","cn":"尽管遭到强烈的反对﹐这项法案还是成为了法律。 Despite her vehement protests, he pulled her inside. 尽管她强烈抗议﹐他还是把她拉了进去。"}]},"vocab":{"pos":"adj","senses":[{"en":"You can use the adjective vehement to describe an extremely strong, powerful, or intense emotion or force. The teenager argued for a much later curfew in a vehement speech to her parents; her parents responded with an equally vehement “No way!”"}]},"media":{"uk":"media/ldoce/hwd/bre/a/vehement0205.mp3","us":"media/ldoce/hwd/ame/2/vehement.mp3"},"examples":[{"en":"a vehement denial/attack/protest, etc.","cn":"强烈的否认、攻击、抗议等"},{"en":"He had been vehement in his opposition to the idea.","cn":"他一直强烈反对这一主张。"}],"oxford":{"phon":"ˈviːəmənt","pos":"adjective","senses":[{"en":"showing very strong feelings, especially anger","cn":"（感情）强烈的，激烈的；（尤指）愤怒的","ex":{"en":"a vehement denial/attack/protest, etc.","cn":"强烈的否认、攻击、抗议等"}}]}},"verbatim":{"collins":{"senses":[{"pos":"ADV 副词","cn":"逐字逐句地;一字不差地","en":"If you repeat something verbatim, you use exactly the same words as were used originally.","ex":{"en":"The President's speeches are regularly reproduced verbatim in the state-run newspapers.","cn":"总统的讲话通常会被一字不差地刊登在国有报纸上。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"completely correct because all the details are true","cn":""},{"en":"an exact copy, model etc of something is like it in every possible way","cn":""},{"en":"a literal translation gives the exact meaning of a word, or each word in a sentence, instead of translating the word or whole sentence in a natural way","cn":""}]},"vocab":{"pos":"adv adj","senses":[{"en":"Repeat something you've read or heard precisely word-for-word, and you have just quoted it verbatim . That's great if what you deliver verbatim is the directions on how to defuse a bomb, but not a good idea if you're cheating on a test and copying someone's answer verbatim ."}]},"media":{"uk":"media/ldoce/hwd/bre/2/verbatim0205.mp3","us":"media/ldoce/hwd/ame/d/verbatim.mp3"},"examples":[{"en":"He reported the speech verbatim.","cn":"他逐字报道了那篇讲话。"},{"en":"a verbatim report","cn":"一字不差的报告"}],"oxford":{"phon":"vɜːˈbeɪtɪm","pos":"adjective, adverb","senses":[{"en":"exactly as spoken or written","cn":"一字不差的（地）；逐字的（地）","ex":{"en":"a verbatim report","cn":"一字不差的报告"}}]}},"venomous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"恶毒的;怨恨的;痛恨的","en":"If you describe a person or their behaviour as venomous, you mean that they show great bitterness and anger towards someone.","ex":{"en":"...his terrifying and venomous Aunt Bridget","cn":"他那可怕而恶毒的布丽奇特姨妈"}},{"pos":"ADJ 形容词","cn":"（蛇、蜘蛛等生物）分泌毒液的，有毒的","en":"A venomous snake, spider, or other creature uses poison to attack other creatures.","ex":{"en":"The adder is Britain's only venomous snake.","cn":"蝰蛇是英国唯一的一种毒蛇。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"full of hatred or anger","cn":"恶毒的﹔充满怨恨的"},{"en":"a venomous snake, insect etc produces poison 〔","cn":"蛇﹑昆虫等〕有毒的﹐分泌毒液的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"An animal that is venomous produces poison. Also, people act in a venomous way when they are cruel, evil, or deliberately harmful."}]},"collocations":{"phrases":["VERBS be","ADV. highly a highly venomous snake | actively There are two types of mollusc that are actively venomous."]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41venomous.mp3","us":"media/ldoce/hwd/ame/8/venomous.mp3"},"examples":[{"en":"a venomous look","cn":"恶狠狠的样子"},{"en":"Lisa shot him a venomous glance.","cn":"莉萨恶狠狠地瞪了他一眼。"}],"oxford":{"phon":"ˈvenəməs","pos":"adjective","senses":[{"en":"producing venom","cn":"分泌毒液的；有毒的","ex":{"en":"a highly venomous snake","cn":"剧毒的蛇"}},{"en":"full of bitter feelings or hate","cn":"恶毒的；恶意的；充满仇恨的","lab":"formal","ex":{"en":"a venomous look","cn":"恶狠狠的样子"}}]}},"verruca":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（脚底长的）疣,肉赘","en":"A verruca is a small infectious lump which grows on the bottom of your foot."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small hard infectious lump that grows on the bottom of your foot 〔","cn":"脚底生的〕疣﹐肉赘"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41verruca.mp3","us":"media/ldoce/hwd/ame/4/ld41verruca.mp3"},"oxford":{"phon":"vəˈruːkə","pos":"noun","senses":[{"en":"a small hard spot like a wart on the bottom of the foot, which can be easily spread from person to person","cn":"（长在脚底上，容易传染的）疣"}]}},"venal":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"贪财的;腐败的;贪赃枉法的;唯利是图的","en":"If you describe someone as venal, you disapprove of them because they are prepared to do almost anything in return for money, even things which are dishonest or immoral.","ex":{"en":"Ian Trimmer is corrupt and thoroughly venal.","cn":"伊恩·特里默贪污受贿，是个彻头彻尾的贪官。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"willing to use power and influence in a dishonest way in return for money 〔","cn":"利用职权〕贪污[受贿]的﹐腐败的"}]},"vocab":{"pos":"adj","senses":[{"en":"Someone with venal motives is corrupt and maybe a little evil. Nobody wants to be thought of as venal ."}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41venal.mp3","us":"media/ldoce/hwd/ame/3/venal.mp3"},"examples":[{"en":"venal journalists","cn":"唯利是图的记者"},{"en":"our venal politicians","cn":"我们腐败的政客"}],"oxford":{"phon":"ˈviːnl","pos":"adjective","senses":[{"en":"prepared to do things that are not honest or moral in return for money","cn":"贪赃枉法的；见利忘义的","ex":{"en":"venal journalists","cn":"唯利是图的记者"}}]}},"ventilate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使（房间或建筑）通风;使空气流通","en":"If you ventilate a room or building, you allow fresh air to get into it.","ex":{"en":"Ventilate the room properly when paint stripping","cn":"当油漆开始剥落时，要给房间适当通风。"}},{"pos":"VERB 动词","cn":"发表（看法）；表达（感情）","en":"If you ventilate your ideas or feelings, you talk about them or express them freely in front of other people.","ex":{"en":"He did not think it the job of officials to ventilate their doubts or daydreams.","cn":"他认为公开提出自己的疑问或不切实际的想法并非官员们的分内之事。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to let fresh air into a room, building etc","cn":"使通风"},{"en":"to pump air into and out of someone’s lungs, using a special machine 〔","cn":"用呼吸机〕给…供氧"},{"en":"to express your opinions or feelings about something","cn":"发表〔意见或看法〕﹔表达〔感情〕"}]},"collocations":{"phrases":["ADV. adequately, properly, well Make sure that the room is well ventilated. | badly, poorly"]},"media":{"uk":"media/ldoce/hwd/bre/c/ventilate0205.mp3","us":"media/ldoce/hwd/ame/a/ventilate.mp3"},"examples":[{"en":"Make sure that there is adequate ventilation in the room before using the paint.","cn":"在使用油漆前确保室内通风充足。"},{"en":"The bathroom is ventilated by means of an extractor fan.","cn":"这个浴室使用抽风扇通风。"}],"oxford":{"phon":"ˈventɪleɪt","pos":"verb","senses":[{"en":"to allow fresh air to enter and move around a room, building, etc.","cn":"使（房间、建筑物等）通风；使通气","g":"[usually passive]","ex":{"en":"The bathroom is ventilated by means of an extractor fan.","cn":"这个浴室使用抽风扇通风。"}},{"en":"to express your feelings or opinions publicly","cn":"公开表达（感情或意见）","lab":"formal"}]}},"vertiginous":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"陡峭的;峻峭的","en":"A vertiginous cliff or mountain is very high and steep.","ex":{"en":"...vertiginous cliffs that rise out of the Baltic.","cn":"波罗的海周边耸立的悬崖峭壁"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"so high that you feel sick and dizzy","cn":"高得令人眩晕的"}]},"vocab":{"pos":"adj","senses":[{"en":"To be vertiginous is to be dizzy and woozy. It's a disorienting feeling."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41vertiginous.mp3","us":"media/ldoce/hwd/ame/3/vertiginous.mp3"},"examples":[{"en":"From the path there was a vertiginous drop to the valley below.","cn":"从小路向谷底望去令人眩晕。"},{"en":"a vertiginous drop to the valley below","cn":"山谷里向下令人眩晕的落差"}],"oxford":{"phon":"vɜːˈtɪdʒɪnəs","pos":"adjective","senses":[{"en":"causing a feeling of vertigo because of being very high","cn":"（因离地很高）令人眩晕的","ex":{"en":"From the path there was a vertiginous drop to the valley below.","cn":"从小路向谷底望去，落差令人眩晕。"}}]}},"velcro":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"维可牢搭链;尼龙搭扣","en":"Velcro is a material consisting of two strips of nylon fabric which you press together to close things such as pockets and bags."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a material used to fasten clothes, consisting of two pieces of material which stick to each other when you press them together","cn":"威扣〔一种钩毛搭扣〕"}]},"media":{"uk":"media/ldoce/hwd/bre/0/velcro0205.mp3","us":"media/ldoce/hwd/ame/3/laadvelcro.mp3","img":["media/thumb/velcro.jpg"]},"oxford":{"phon":"ˈvelkrəʊ","pos":"noun","senses":[{"en":"a material with two different surfaces, one rough and one smooth, that stick to each other when they are pressed together, used for fastening clothes, etc.","cn":"威扣魔术贴"}]}},"venerable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（因年高睿智）德高望重的，令人崇敬的","en":"A venerable person deserves respect because they are old and wise.","ex":{"en":"Her Chinese friends referred to the Empress as their venerable ancestor.","cn":"她的中国朋友们说这位女皇是他们值得敬仰的祖先。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（因年代久远或具有重要历史价值）令人仰慕的，神圣庄严的","en":"Something that is venerable is impressive because it is old or important historically.","ex":{"en":"May Day has become a venerable institution","cn":"五朔节已经变成一个神圣庄严的传统节日。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a venerable person or thing is respected because of their great age, experience etc – often used humorously 〔","cn":"由于年龄﹑经验而〕令人尊敬的，年高德劭的〔常为幽默用法〕"},{"en":"in the Church of England, the title given to an archdeacon","cn":"尊者…〔英国国教中对副主教的尊称〕"},{"en":"in the Roman Catholic religion, the title given to a dead person who is holy but not yet a saint","cn":"尊者…〔天主教对圣洁者但还不是圣徒的已故者的称号〕"}]},"vocab":{"pos":"adj","senses":[{"en":"To be venerable is to be admired and respected because of your status or age. You become venerable by achieving great things or just by living long enough."}]},"media":{"uk":"media/ldoce/hwd/bre/1/venerable0205.mp3","us":"media/ldoce/hwd/ame/9/ld44venerable.mp3"},"examples":[{"en":"the Venerable Martin Roberts","cn":"尊者马丁 · 罗伯茨"},{"en":"a venerable old man","cn":"德高望重的老人"}],"oxford":{"phon":"ˈvenərəbl","pos":"adjective","senses":[{"en":"venerable people or things deserve respect because they are old, important, wise, etc.","cn":"（因年高、显要、智慧等）令人尊重的，值得敬重的，受敬佩的","g":"[usually before noun]","lab":"formal","ex":{"en":"The president was a venerable old man with white hair and a gracious manner.","cn":"总统是一位德高望重的老人，头发花白，举止和蔼。"}},{"en":"(in the Anglican Church) a title of respect used when talking about an archdeacon","cn":"（对圣公会会吏长的尊称）尊者","g":"[only before noun]","ex":{"en":"the Venerable Martin Roberts","cn":"尊者马丁·罗伯茨"}},{"en":"(in the Roman Catholic Church) a title given to a dead person who is very holy but who has not yet been made a saint","cn":"真福（天主教会对列入圣品前的已故圣洁者的尊称）","g":"[only before noun]"}]}},"vespers":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（某些基督教派的）晚祷","en":"In some Christian churches, vespers is a service in the evening."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the evening service in some types of Christian church 〔","cn":"基督教某些教派的〕晚祷"}]},"media":{"uk":"media/ldoce/hwd/bre/f/vespers0205.mp3","us":"media/ldoce/hwd/ame/5/vespers.mp3"},"oxford":{"phon":"ˈvespəz","pos":"noun","senses":[{"en":"the service of evening prayer in some Christian Churches","cn":"（基督教某些教派的）晚课，晚祷"}]}},"veg":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"蔬菜","en":"Veg are plants such as cabbages, potatoes, and onions which you can cook and eat. Veg is an abbreviation for (缩略=) 'vegetables'.","ex":{"en":"...fruit and veg.","cn":"水果和蔬菜"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"vegetables","cn":"蔬菜"},{"en":"to be very lazy and spend time doing very little","cn":"懒散地打发时间"}]},"media":{"uk":"media/ldoce/hwd/bre/9/veg_n0205.mp3","us":"media/ldoce/hwd/ame/9/ld41veg.mp3"},"examples":[{"en":"He likes the traditional meat and two veg for his main meal.","cn":"他主餐喜欢传统的一荤两素。"},{"en":"a fruit and veg stall","cn":"水果蔬菜摊位"}],"oxford":{"phon":"vedʒ","pos":"noun","senses":[{"en":"a vegetable or vegetables","cn":"蔬菜","ex":{"en":"a fruit and veg stall","cn":"水果蔬菜摊位"}},{"en":"suitable for a person who does not eat meat or fish; not containing or serving meat or fish","cn":"素食者的；素食的","ex":{"en":"We have a choice of veg options.","cn":"我们有各类素食供选用。"},"pos":"adjective"},{"en":"eating no meat or fish","cn":"素食的；吃素的","ex":{"en":"Veg travellers are well-catered for: the local restaurants offer both veg and non-veg options.","cn":"素食旅行者可以得到很好的照顾：当地餐厅提供素食和非素食选择。"},"pos":"adjective"}]}},"vengeful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有复仇心理的；图谋报复的;想报仇的","en":"If you describe someone as vengeful, you are critical of them because they feel a great desire for revenge.","ex":{"en":"He was stabbed to death by his vengeful wife","cn":"他被图谋报复的妻子拿刀捅死了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very eager to punish someone who has done something bad","cn":"有复仇心理的﹔图谋报复的﹐复仇的"}]},"vocab":{"pos":"adj","senses":[{"en":"Hope that there's no one out there who has vengeful feelings toward you, or wants to get back at you for something that you've done to them. A vengeful person is out for revenge."}]},"media":{"uk":"media/ldoce/hwd/bre/2/vengeful0205.mp3","us":"media/ldoce/hwd/ame/e/vengeful.mp3"},"examples":[{"en":"a vengeful god","cn":"复仇之神"}],"oxford":{"phon":"ˈvendʒfl","pos":"adjective","senses":[{"en":"showing a desire to punish somebody who has harmed you","cn":"心存报复的；图谋复仇的","ex":{"en":"He was not a vengeful man.","cn":"他不是一个记仇的人。"}}]}},"venturesome":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有冒险精神的;大胆的","en":"If you describe someone as venturesome, you mean that they are willing to take risks and try out new things.","ex":{"en":"...the venturesome graduate who is determined to succeed.","cn":"敢闻敢干、决心要出人头地的毕业生"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"willing to take risks","cn":"大胆的﹐爱冒险的"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective venturesome describes someone who is willing to take risks, someone brave. If you have a venturesome child, you may worry because she's the one you find on top of the playhouse instead of inside it."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41venturesome.mp3","us":"media/ldoce/hwd/ame/8/venturesome.mp3"},"oxford":{"phon":"ˈventʃəsəm","pos":"adjective","senses":[{"en":"willing to take risks","cn":"大胆的；好冒险的"}]}},"verbalize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"用言语表达;用文字描述","en":"If you verbalize your feelings, thoughts, or ideas, you express them in words.","ex":{"en":"...his inability to verbalize his feelings.","cn":"他无法用言语表达自己的感情"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to express something in words","cn":"用言语［文字］表达"}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"To verbalize something is to put it into words. If you need to get into the bathroom desperately, and the person in front of you hasn’t noticed your agitation, you’ll probably have to verbalize it, and quickly!"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41verbalize.mp3","us":"media/ldoce/hwd/ame/6/laadverbalize.mp3"},"examples":[{"en":"He's a real genius but he has difficulty verbalizing his ideas.","cn":"他确实是个天才，可是难以用语言表达他的思想。"},{"en":"Urge your child to verbalize his feelings.","cn":"鼓励你的孩子用言语表达自己的情感。"}],"oxford":{"phon":"ˈvɜːbəlaɪz","pos":"verb","senses":[{"en":"to express your feelings or ideas in words","cn":"用言语（或文字）表达","ex":{"en":"He's a real genius but he has difficulty verbalizing his ideas.","cn":"他确实是个天才，但不太会表达自己的想法。"}}]}},"veto":{"collins":{"senses":[{"pos":"VERB 动词","cn":"否决;否定","en":"If someone in authority vetoes something, they forbid it, or stop it being put into action.","ex":{"en":"De Gaulle vetoed Britain's application to join the EEC","cn":"戴高乐驳回了英国加入欧洲经济共同体的申请。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"否决权","en":"Veto is the right that someone in authority has to forbid something.","ex":{"en":"...the President's power of veto.","cn":"总统的否决权"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say firmly that you will not do something that someone has asked you to do","cn":""},{"en":"to say that you will not do something when someone asks you","cn":""},{"en":"to refuse to accept an offer or invitation, or a formal request","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A veto is a no vote that blocks a decision. The President can veto some bills that pass his desk."}]},"collocations":{"phrases":["ADJ. effective, virtual | absolute | government, presidential","VERB + VETO have | cast, exercise, impose, use The board can exercise its veto to prevent the decision. | lift The agreement became possible","VETO + NOUN power, rights","PREP. ~ against The nobles had a virtual veto against peasant candidates. | ~ on The Opposition effectively have a veto on constitutional re","PHRASES a power/right of veto"]},"media":{"uk":"media/ldoce/hwd/bre/e/veto_v0205.mp3","us":"media/ldoce/hwd/ame/5/veto1.mp3"},"examples":[{"en":"I wanted to go camping but the others quickly vetoed that idea.","cn":"我想去野营，但这个想法很快遭到了其他人的反对。"},{"en":"The British government used its veto to block the proposal.","cn":"英国政府行使其否决权阻止了这项提案。"}],"oxford":{"phon":"ˈviːtəʊ","pos":"noun","senses":[{"en":"the right to refuse to allow something to be done, especially the right to stop a law from being passed or a decision from being taken","cn":"否决权","g":"[countable, uncountable]","ex":{"en":"The British government used its veto to block the proposal.","cn":"英国政府行使其否决权阻止了这项提案。"}},{"en":"an occasion when somebody refuses to allow something to be done","cn":"拒绝认可；禁止","g":"[countable]","ex":{"en":"For months there was a veto on employing new staff.","cn":"有好几个月禁止雇用新职员。"}},{"en":"to stop something from happening or being done by using your official authority (= by using your veto)","cn":"行使否决权；拒绝认可；禁止","lab":"especially North American English","ex":{"en":"Plans for the dam have been vetoed by the Environmental Protection Agency.","cn":"修建大坝的计划已被环境保护局否决。"},"pos":"verb"},{"en":"to refuse to accept or do what somebody has suggested","cn":"拒不接受；反对；否定","ex":{"en":"I wanted to go camping but the others quickly vetoed that idea.","cn":"我想去野营，但这个想法很快遭到了其他人的反对。"},"pos":"verb"}]}},"vernacular":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"方言;土语;地方话","en":"The vernacular is the language or dialect that is most widely spoken by ordinary people in a region or country.","ex":{"en":"...books or plays written in the vernacular","cn":"用方言写就的书或戏剧"}},{"pos":"ADJ 形容词","cn":"（建筑）民间风格的","en":"Vernacular architecture is the style of architecture in which ordinary people's houses are built in a particular region.","ex":{"en":"...the island's vernacular architecture.","cn":"岛上具有当地风格的建筑"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a form of a language that ordinary people use, especially one that is not the official language 〔","cn":"尤指非官方语言的〕本国语﹐本地语﹐土话﹐方言"},{"en":"a style of building, music, art etc that is suitable for ordinary people 〔","cn":"建筑﹑音乐﹑艺术等的〕民间风格"}]},"vocab":{"pos":"n adj","senses":[{"en":"Vernacular describes everyday language, including slang, that's used by the people. The vernacular is different from literary or official language: it's the way people really talk with each other, like how families talk at home."}]},"media":{"uk":"media/ldoce/hwd/bre/a/vernacular0205.mp3","us":"media/ldoce/hwd/ame/8/vernacular.mp3"},"examples":[{"en":"Galileo wrote in the vernacular to reach a larger audience.","cn":"为了让更多读者看懂﹐伽利略用本国语言写作。"},{"en":"He lapsed into the local vernacular (= language spoken in a particular area ) .","cn":"他说着说着就讲起了地方土话。"}],"oxford":{"phon":"vəˈnækjələ(r)","pos":"noun","senses":[{"en":"the language spoken by ordinary people in a particular country or region","cn":"方言；土语","g":"[singular]"},{"en":"a style of architecture used for ordinary houses rather than large public buildings","cn":"（建筑的）民间风格","g":"[uncountable]","lab":"specialist"},{"en":"spoken by ordinary people in a particular country or region; using a vernacular language","cn":"方言的；土语的","ex":{"en":"English vernacular poetry","cn":"英国白话诗"},"pos":"adjective"},{"en":"in a style that is used for ordinary houses rather than large public buildings","cn":"民间风格的","lab":"specialist","ex":{"en":"vernacular domestic architecture","cn":"乡土住宅建筑"},"pos":"adjective"}]}},"vendor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小贩;摊贩","en":"A vendor is someone who sells things such as newspapers, cigarettes, or food from a small stall or cart.","ex":{"en":"...ice-cream vendors.","cn":"卖冰激凌的小贩"}},{"pos":"N-COUNT 可数名词","cn":"（房地产的）卖主，卖方","en":"The vendor of a house or piece of land is the person who owns it and is selling it.","ex":{"en":"Remember, the estate agent is working for the vendor.","cn":"记住，房地产代理商是为房地产卖方服务的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who owns or is in charge of a small shop","cn":""},{"en":"someone who owns a small shop","cn":""},{"en":"someone who owns or is in charge of a shop","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you are a vendor , it means you’re a person selling something, whether it’s hot dogs from a food cart or computer software for a tech company."}]},"media":{"uk":"media/ldoce/hwd/bre/2/vendor0205.mp3","us":"media/ldoce/hwd/ame/9/laadvendor.mp3"},"examples":[{"en":"software vendors","cn":"软件销售商"},{"en":"street vendors","cn":"街头小贩"}],"oxford":{"phon":"ˈvendə(r)","pos":"noun","senses":[{"en":"a person who sells things, for example food or newspapers, usually outside on the street","cn":"小贩；摊贩","ex":{"en":"Jewellery, leather and clothes are offered by street vendors at every corner.","cn":"街头巷尾到处都有小贩出售首饰、皮革制品和服装。"}},{"en":"a company that sells a particular product","cn":"（某种产品的）销售公司","lab":"formal","ex":{"en":"software vendors","cn":"软件销售商"}},{"en":"a person who is selling a house, etc.","cn":"（房屋等的）卖主","lab":"law","ex":{"en":"The cost to the vendor of selling land by auction is normally higher than by private treaty.","cn":"以拍卖方式出售土地时卖主支付的费用通常高于私下协议的方式。"}}]}},"verisimilitude":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"真实性;逼真","en":"Verisimilitude is the quality of seeming to be true or real.","ex":{"en":"At the required level of visual verisimilitude, computer animation is costly.","cn":"要使电脑动画的视觉效果达到要求的逼真程度，花费会十分昂贵。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the quality of being true or real","cn":"真实性﹔逼真"}]},"vocab":{"pos":"n","senses":[{"en":"Verisimilitude means being believable, or having the appearance of being true. You can improve your play by using the sounds and smells of the beach as well as lots of sand to create verisimilitude ."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41verisimilitude.mp3","us":"media/ldoce/hwd/ame/a/verisimilitude.mp3"},"examples":[{"en":"To add verisimilitude, the stage is covered with sand for the desert scenes.","cn":"为了更加逼真，舞台上铺满了沙子作为沙漠的场景。"},{"en":"questions about the verisimilitude of the document","cn":"针对这份文件的真实性提出的问题"}],"oxford":{"phon":"ˌverɪsɪˈmɪlɪtjuːd","pos":"noun","senses":[{"en":"the quality of seeming to be true or real","cn":"貌似真实；逼真","ex":{"en":"To add verisimilitude, the stage is covered with sand for the desert scenes.","cn":"为了更加逼真，舞台上铺满了沙子作为沙漠的场景。"}}]}},"vermont":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a state in the northeastern US, which is part of New England. Vermont produces many minerals, and also maple syrup , and attracts many visitors for skiing ( ski ), hunting, and fishing.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/p028-000012559.mp3","us":"media/ldoce/hwd/ame/1/p028-000012559.mp3"},"oxford":{"phon":"vəˈmɒnt","pos":"","senses":[{"en":"a New England state in the US, on the border with Canada. It is also known as the Green Mountain State. The largest city is Burlington and the capital city is Montpelier. The French settled there first in the 17th century, and Vermont became a state in 1791. It produces different types of stone, including granite and marble, and other products include electrical equipment, paper, furniture and maple syrup (= a sweet, sticky sauce produced from a type of maple tree). Tourist attractions in Vermont include the Green Mountain National Forest and the Bennington Battle Monument.","cn":"佛蒙特（美国东北部新英格兰地区的州，与加拿大接界。最大城市伯灵顿，首府蒙彼利埃）"}]}},"venison":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"鹿肉","en":"Venison is the meat of a deer."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the meat of a deer","cn":"鹿肉"}]},"vocab":{"pos":"n","senses":[{"en":"Bambi, beware. Venison is deer meat intended as food."}]},"media":{"uk":"media/ldoce/hwd/bre/8/venison0205.mp3","us":"media/ldoce/hwd/ame/7/venison.mp3"},"oxford":{"phon":"ˈvenɪsn","pos":"noun","senses":[{"en":"meat from a deer","cn":"鹿肉"}]}},"verge":{"collins":{"senses":[{"pos":"PREP-PHRASE 短语介词","cn":"即将;接近于;濒于","en":"If you are on the verge of something, you are going to do it very soon or it is likely to happen or begin very soon.","ex":{"en":"The country was on the verge of becoming prosperous and successful","cn":"这个国家即将走向繁荣富强。"}},{"pos":"N-COUNT 可数名词","cn":"路边;(道路的)植草边沿","en":"The verge of a road is a narrow piece of ground by the side of a road, which is usually covered with grass or flowers."},{"pos":"","cn":"","en":"相关词组：verge on"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"not completely or exactly, but almost - use this when the difference is not important","cn":""},{"en":"almost completely","cn":""},{"en":"not completely, but almost - use this to say that something has not happened, but that it almost has","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"Think of an edge, a border, a boundary, and you are thinking about the verge , the point where something begins or ends."}]},"collocations":{"phrases":["ADJ. grass | motorway, roadside","VERB + VERGE bring sb/sth to (figurative) This action brought the country to the verge of economic collapse.","PREP. on the ~ (figurative) She was on the verge of a nervous breakdown when she finally sought help."]},"media":{"uk":"media/ldoce/hwd/bre/8/verge_v0205.mp3","us":"media/ldoce/hwd/ame/5/verge1.mp3"},"examples":[{"en":"Some of his suggestions verged on the outrageous.","cn":"他的一些建议都快到了荒唐的地步。"},{"en":"They are on the verge of signing a new contract.","cn":"他们即将签订一份新的合同。"}],"oxford":{"phon":"vɜːdʒ","pos":"noun","senses":[{"en":"a piece of grass at the edge of a path, road, etc.","cn":"（路边的）小草地，绿地","ex":{"en":"a grass verge","cn":"长了草的路边"}}]}},"velvety":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"天鹅绒般的;柔软光滑的","en":"If you describe something as velvety, you mean that it is pleasantly soft to touch and has the appearance or quality of velvet.","ex":{"en":"The grass grew thick and velvety","cn":"草长得又茂密又柔软。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"covered in soft, light threads, fur, or feathers","cn":""},{"en":"soft, smooth, and shiny and pleasant to touch","cn":""},{"en":"looking, feeling, tasting, or sounding smooth and soft","cn":"柔软光滑的﹔圆润轻柔的"}]},"vocab":{"pos":"adj","senses":[{"en":"Anything velvety is smooth or soft in some way, like creamy chocolate or a soothing voice."}]},"media":{"uk":"media/ldoce/hwd/bre/8/velvety0205.mp3","us":"media/ldoce/hwd/ame/7/velvety.mp3"},"examples":[{"en":"a velvety red wine","cn":"醇厚的红葡萄酒"},{"en":"velvety skin","cn":"柔软的皮肤"}],"oxford":{"phon":"ˈvelvəti","pos":"adjective","senses":[{"en":"pleasantly smooth and soft","cn":"光滑柔软的；柔和的","lab":"figurative","ex":{"en":"velvety skin","cn":"柔软的皮肤"}}]}},"verbose":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冗长的;啰唆的;唠叨的","en":"If you describe a person or a piece of writing as verbose, you are critical of them because they use more words than are necessary, and so make you feel bored or annoyed.","ex":{"en":"...verbose politicians","cn":"长篇大论的政治家们"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"using or containing too many words","cn":"啰唆的﹐累赘的﹐冗长的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you're verbose , you use far more words than you need to. A verbose book report goes on and on and is packed with long, complicated words that aren't at all necessary."}]},"media":{"uk":"media/ldoce/hwd/bre/3/verbose0205.mp3","us":"media/ldoce/hwd/ame/e/verbose.mp3"},"examples":[{"en":"a verbose speaker/style","cn":"罗里罗嗦的演讲者；长篇大论"},{"en":"For once, his usually verbose wife was content to listen.","cn":"他那个一贯唠叨的老婆难得一次愿意倾听。"}],"oxford":{"phon":"vɜːˈbəʊs","pos":"adjective","senses":[{"en":"using or containing more words than are needed","cn":"冗长的；啰唆的；唠叨的","ex":{"en":"a verbose speaker/style","cn":"啰里啰唆的演讲者；长篇大论"}}]}},"vein":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"静脉","en":"Your veins are the thin tubes in your body through which your blood flows towards your heart.","ex":{"en":"Many veins are found just under the skin.","cn":"许多静脉血管就在皮肤下面。"}},{"pos":"N-COUNT 可数名词","cn":"（行文的）风格;（说话的）语气，情绪","en":"Something that is written or spoken in a particular vein is written or spoken in that style or mood.","ex":{"en":"It is one of his finest works in a lighter vein","cn":"这是他行文风格轻松活泼的作品中最出色的作品之一。"}},{"pos":"N-COUNT 可数名词","cn":"几分，若干（指在某人的行为或工作中常表现出的某种品质）","en":"A vein of a particular quality is evidence of that quality which someone often shows in their behaviour or work.","ex":{"en":"The striker's rich vein of form this season has seen him net 32 goals","cn":"这位前锋本赛季状态奇佳，进球已达到32个。"}},{"pos":"N-COUNT 可数名词","cn":"矿脉;矿层;岩脉","en":"A vein of a particular metal or mineral is a layer of it lying in rock.","ex":{"en":"...a vein of copper.","cn":"铜矿层"}},{"pos":"N-COUNT 可数名词","cn":"（叶子的）纹路，纹理;叶脉","en":"The veins on a leaf are the thin lines on it.","ex":{"en":"...the serrated edges and veins of the feathery leaves.","cn":"羽状叶子的锯齿边沿和纹理"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the tubes which carries blood to your heart from other parts of your body","cn":"静脉"},{"en":"one of the thin lines on a leaf or on an insect’s wing 〔","cn":"植物的〕叶脉﹔〔昆虫的〕翅脉"},{"en":"one of the thin lines on a piece of cheese or some types of stone 〔","cn":"干酪﹑石头等的〕纹理﹐纹路"}]},"vocab":{"pos":"n v","senses":[{"en":"A vein is a blood vessel. If you've ever donated blood, you know that having a needle put in your vein by a health care worker is not nearly as scary as it sounds."}]},"collocations":{"phrases":["ADJ. blue A blue vein throbbed in his forehead. | broken, thread, varicose She uses make-up to hide the thread veins in her cheeks. | jugula","VERB + VEIN course/run along/through, flow through, pump through, race through, rush through He felt the adrenalin coursing through his vein","VEIN + VERB bulge, pulse, stand out, throb The veins stood out on her throat and temples. 2 particular style/quality","ADJ. rich","VERB + VEIN hit, strike The team have hit a rich vein of form recently. | tap (into)","PREP. ~ of The writer tapped into a rich vein of humour in the play.","PHRASES in a different vein, in a lighter/more serious vein Fortunately, the rest of the evening continued in a lighter vein. | in the same "]},"media":{"img":["media/ldoce/img/body.jpg"],"uk":"media/ldoce/hwd/bre/2/vain0205.mp3","us":"media/ldoce/hwd/ame/1/vain.mp3"},"examples":[{"en":"‘And that's not all,’ he continued in angry vein. “","cn":"那还不算全部呢。”他生气地继续说道。"},{"en":"They had tapped a rich vein of information in his secretary.","cn":"他们从他的秘书那里摸到了大量信息。"}],"oxford":{"phon":"veɪn","pos":"noun","senses":[{"en":"any of the tubes that carry blood from all parts of the body towards the heart","cn":"静脉","g":"[countable]","ex":{"en":"the jugular vein","cn":"颈静脉"}},{"en":"any of the very thin tubes that form the frame of a leaf or an insect’s wing","cn":"叶脉；翅脉","g":"[countable]"},{"en":"a narrow area of a different colour in some types of stone, wood and cheese","cn":"纹理；纹路；条纹","g":"[countable]"},{"en":"a thin layer of minerals or metal contained in rock","cn":"矿脉；矿脉床；矿层；岩脉","g":"[countable]","ex":{"en":"a vein of gold","cn":"金矿脉"}},{"en":"an amount of a particular quality or feature in something","cn":"（某种素质或特征的）量","g":"[singular]","ex":{"en":"They had tapped a rich vein of information in his secretary.","cn":"他们从他的秘书那里摸到了大量信息。"}},{"en":"a particular style or manner","cn":"风格；方式","g":"[singular, uncountable]","ex":{"en":"A number of other people commented in a similar vein.","cn":"其他一些人也以类似的腔调评论。"}}]}},"vestry":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(教堂的）法衣室","en":"A vestry is a room in a church which the clergy use as an office or to change into their ceremonial clothes for church services."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small room in a church where a priest puts on his or her vestments and where holy plates, cups etc are kept 〔","cn":"教堂的〕法衣室﹐圣具室"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41vestry.mp3","us":"media/ldoce/hwd/ame/f/vestry.mp3"},"oxford":{"phon":"ˈvestri","pos":"noun","senses":[{"en":"a room in a church where a priest prepares for a service by putting on special clothes and where various objects used in worship are kept","cn":"（教堂的）祭衣圣器储藏室"}]}},"ventriloquist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"腹语术表演者;口技表演者","en":"A ventriloquist is someone who can speak without moving their lips and who entertains people by making their words appear to be spoken by a puppet","ex":{"en":"He looked like a ventriloquist's dummy.","cn":"他看上去像腹语术表演者用的人偶。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who entertains people by speaking without moving their lips and making it seem that the words are spoken by a model of a person called a dummy","cn":"腹语术表演者﹐口技表演者"}]},"vocab":{"pos":"n","senses":[{"en":"Ventriloquists prove that even adults sometimes play with dolls. Specifically, these performers pretend to make their dolls, puppets, or dummies speak for entertainment purposes."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ventriloquist0205.mp3","us":"media/ldoce/hwd/ame/c/laadventriloquist.mp3"},"examples":[{"en":"Entertainment included a ventriloquist.","cn":"演出的包括一名口技表演者。"},{"en":"a ventriloquist's dummy","cn":"表演口技用的傀儡"}],"oxford":{"phon":"venˈtrɪləkwɪst","pos":"noun","senses":[{"en":"a person who entertains by speaking without moving their lips and making it look as if their voice is coming from a puppet or another person","cn":"腹语术，口技（嘴唇不动、声音像来自他人的发声技巧）","ex":{"en":"Entertainment included a ventriloquist.","cn":"演出的包括一名腹语表演者。"}}]}},"versatile":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有多种技能的;多才多艺的","en":"If you say that a person is versatile, you approve of them because they have many different skills.","ex":{"en":"He had been one of the game's most versatile athletes.","cn":"他是这项运动中技术最全面的运动员之一。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有多种用途的;多功能的","en":"A tool, machine, or material that is versatile can be used for many different purposes.","ex":{"en":"Never before has computing been so versatile.","cn":"计算机的用途从没像现在这么广泛过。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"good at doing a lot of different things and able to learn new skills quickly and easily","cn":""},{"en":"someone who is good at doing a lot of different things","cn":""},{"en":"something that is versatile can be used in many different ways","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To describe a person or thing that can adapt to do many things or serve many functions, consider the adjective versatile ."}]},"collocations":{"phrases":["VERBS be, prove, seem","ADV. amazingly, extremely, highly, very, wonderfully This machine is amazingly versatile. | fairly, quite"]},"media":{"uk":"media/ldoce/hwd/bre/5/versatile0205.mp3","us":"media/ldoce/hwd/ame/9/versatile.mp3"},"examples":[{"en":"He's a versatile actor who has played a wide variety of parts.","cn":"他是个多才多艺的演员，扮演过各种各样的角色。"},{"en":"Eggs are easy to cook and are an extremely versatile food.","cn":"鸡蛋容易烹煮，怎么做着吃都行。"}],"oxford":{"phon":"ˈvɜːsətaɪl","pos":"adjective","senses":[{"en":"able to do many different things","cn":"多才多艺的；有多种技能的；多面手的","ex":{"en":"He's a versatile actor who has played a wide variety of parts.","cn":"他是个多才多艺的演员，扮演过各种各样的角色。"}},{"en":"having many different uses","cn":"多用途的；多功能的","ex":{"en":"Eggs are easy to cook and are an extremely versatile food.","cn":"鸡蛋容易烹煮，怎么做着吃都行。"}}]}},"versed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精通的;通晓的","en":"If you are versed in or well versed in something, you know a lot about it.","ex":{"en":"Page is well versed in many styles of jazz.","cn":"佩奇精通多种风格的爵士乐。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"knowing a lot of facts about a particular subject, especially about something that not many people know about","cn":""},{"en":"to know a lot about a particular subject because you have had a lot of experience of it","cn":""},{"en":"to know a particular subject very thoroughly","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To be versed in something is to know it well and have experience with it. If you’re well versed in Middle English literature, you know that Chaucer wrote The Canterbury Tales in 1475. Go you."}]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdeversed.mp3","us":"media/ldoce/hwd/ame/c/versed.mp3"},"examples":[{"en":"He was well versed in employment law.","cn":"他精通雇佣法。"},{"en":"a woman well versed in the art of diplomacy","cn":"熟谙外交手腕的女人"}],"oxford":{"phon":"vɜːst","pos":"adjective","senses":[{"en":"having a lot of knowledge about something, or skill at something","cn":"精通的；熟练的","ex":{"en":"He was well versed in employment law.","cn":"他精通雇佣法。"}}]}},"veined":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（皮肤）显出静脉的,青筋暴露的","en":"Veined skin has a lot of veins showing through it.","ex":{"en":"Helen's hands were thin and veined.","cn":"海伦的双手枯瘦，青筋凸起。"}},{"pos":"ADJ 形容词","cn":"有纹理的;有脉纹的","en":"Something that is veined has a pattern or colouring like that of veins showing through skin.","ex":{"en":"...a bronze ashtray shaped like a veined leaf.","cn":"外形如一片叶脉清晰的叶子的铜制烟灰缸"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a pattern of thin lines on the surface","cn":"有纹理的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/veined0205.mp3","us":"media/ldoce/hwd/ame/7/veined.mp3"},"examples":[{"en":"thin blue-veined hands","cn":"青筋暴突的瘦弱的双手"},{"en":"veined marble","cn":"有纹理的大理石"}],"oxford":{"phon":"veɪnd","pos":"adjective","senses":[{"en":"having or marked with veins or thin lines","cn":"有静脉的；有叶脉的；有翅脉的；有纹理的","ex":{"en":"thin blue-veined hands","cn":"青筋暴突的瘦弱的双手"}}]}},"verbiage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"冗词;赘语;废话","en":"If you refer to someone's speech or writing as verbiage, you are critical of them because they use too many words, which makes their speech or writing difficult to understand.","ex":{"en":"Stripped of their pretentious verbiage, his statements come dangerously close to inviting racial hatred.","cn":"抛开那些夸大其词的冗词赘语不论，他的言论有挑起种族仇恨的危险。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"speech or writing that has many unnecessary words in it 〔","cn":"说话或写作的〕冗词﹐啰唆﹐赘语"}]},"vocab":{"pos":"n","senses":[{"en":"Verbiage is what it sounds like — a lot of words: verbs, nouns, adjectives and all the other parts of speech. Usually, verbiage means a few too many words — like the excessive verbiage in a legal document."}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41verbiage.mp3","us":"media/ldoce/hwd/ame/b/verbiage.mp3"},"examples":[{"en":"meaningless verbiage","cn":"不知所云的冗词"}],"oxford":{"phon":"ˈvɜːbiɪdʒ","pos":"noun","senses":[{"en":"the use of too many words, or of more difficult words than are needed, to express an idea","cn":"冗词；赘语；晦涩"}]}},"vestige":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"残余;残留部分;遗迹","en":"A vestige of something is a very small part that still remains of something that was once much larger or more important.","ex":{"en":"We represent the last vestige of what made this nation great — hard work.","cn":"是辛勤劳动成就了这个国家，而我们就是这一品质硕果仅存的代表。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small part or amount of something that remains when most of it no longer exists","cn":"痕迹﹐遗迹﹔残余"},{"en":"the smallest possible amount of a quality or feeling","cn":"一点﹐丝毫"}]},"vocab":{"pos":"n","senses":[{"en":"Vestige is an elegant word. It's all about shadows, and gives us a way to talk about traces or reminders of something that has disappeared or is disappearing."}]},"collocations":{"phrases":["ADJ. last, remaining The government has to remove any last vestiges of corruption.","VERB + VESTIGE lose, shed | dispel, remove, strip sb/sth of | preserve, retain I'm struggling to retain any vestige of belief in his innocen","PREP. without a ~ He looked at her without a vestige of sympathy. | ~ of"]},"media":{"uk":"media/ldoce/hwd/bre/f/vestige0205.mp3","us":"media/ldoce/hwd/ame/f/vestige.mp3"},"examples":[{"en":"There's not a vestige of truth in the rumour.","cn":"这个谣传毫无真实可言。"},{"en":"the last vestiges of the old colonial regime","cn":"旧殖民制度最后的残余"}],"oxford":{"phon":"ˈvestɪdʒ","pos":"noun","senses":[{"en":"a small part of something that still exists after the rest of it has stopped existing","cn":"残留部分；遗迹","ex":{"en":"the last vestiges of the old colonial regime","cn":"旧殖民制度最后的残余"}},{"en":"usually used in negative sentences, to say that not even a small amount of something exists","cn":"（通常用于否定句）丝毫，一点儿","ex":{"en":"There's not a vestige of truth in the rumour.","cn":"这个谣传毫无真实可言。"}}]}},"verbal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"口头的;非书面的;非行动的","en":"You use verbal to indicate that something is expressed in speech rather than in writing or action.","ex":{"en":"They were jostled and subjected to a torrent of verbal abuse","cn":"他们被推来搡去，受到大肆的谩骂攻击。"}},{"pos":"ADJ 形容词","cn":"文字的;词语的;用文字表达的","en":"You use verbal to indicate that something is connected with words and the use of words.","ex":{"en":"The test has scores for verbal skills, mathematical skills, and abstract reasoning skills","cn":"测试包含对语言能力、数学能力和抽象推理能力的考查。"}},{"pos":"ADJ 形容词","cn":"动词的","en":"In grammar, verbal means relating to a verb.","ex":{"en":"...a verbal noun.","cn":"动名词"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used about the language that people speak rather than write","cn":""},{"en":"an oral test is one in which you have to speak rather than write. Oral is also used about culture, traditions, and history that are based on spoken English rather than being written down","cn":""},{"en":"a verbal agreement, warning, form of communication etc is spoken rather than written down","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If your friend tells you that the speech you just made was really verbal , he means you used too many words, overstated the point, went on too long, were redundant."}]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdeverbal.mp3","us":"media/ldoce/hwd/ame/d/verbal.mp3"},"examples":[{"en":"The job applicant must have good verbal skills.","cn":"应聘这份工作的人必须具有良好的语言表达技能。"},{"en":"non-verbal communication (= expressions of the face, gestures , etc.)","cn":"非语言交际"}],"oxford":{"phon":"ˈvɜːbl","pos":"adjective","senses":[{"en":"relating to words","cn":"文字的；言语的；词语的","ex":{"en":"The job applicant must have good verbal skills.","cn":"应聘这份工作的人必须具有良好的语言表达技能。"}},{"en":"spoken, not written","cn":"口头（而非书面）的","ex":{"en":"a verbal agreement/warning","cn":"口头协议／警告"}},{"en":"relating to verbs","cn":"动词的","lab":"grammar","ex":{"en":"a verbal noun (= a noun formed from a verb, for example smoking)","cn":"动名词"}}]}}});
